          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"a53b026d-3a56-59ed-ba62-5a8dd03c30d0","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -ضرب باستخدام مفتاح سيارة -إحداث إصابة -وجود سوابق قضائية -ثبوت اإلدانة -تعزير بالسجن واجللد -","document_number":"3429077","case_number":"33695048","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/4","year":"1434","subject":"اعتداء -ضرب -ضرب باستخدام مفتاح سيارة -إحداث إصابة -وجود سوابق قضائية -ثبوت اإلدانة -تعزير بالسجن واجللد -","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"          ‫رقم الصك ‪ 3429077 :‬تاريخه‪1434/2/4 :‬هـ‬\n                            ‫رقم الدعوى‪33695048:‬‬\n             ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                    ‫‪ 3450975‬تاريخه‪1434/5/7 :‬هـ‬\n\n\n\n      ‫اعتــداء ‪ -‬ضــرب ‪ -‬ضــرب باســتخدام مفتــاح ســيارة ‪ -‬إحــداث إصابــة‬\n      ‫‪ -‬وجــود ســوابق قضائيــة ‪ -‬ثبــوت اإلدانــة ‪ -‬تعزيــر بالســجن واجللــد ‪-‬‬\n                                                                   ‫أخــذ تعهــد‪.‬‬\n\n\n\n\n      ‫ض َب ْع َد ِإ ْص َل ِح َها ) وقال تعالى‪:‬‬                       ‫‪ -‬قال اهلل تعالى‪َ ( :‬و َل ُت ْف ِس ُدوا ِف ْ َ‬\n                                                               ‫ال ْر ِ‬\n                                                                ‫ين ) ‪.‬‬ ‫الل ال ُي ِح ُّب ْالُ ْع َتدِ َ‬     ‫( َوال َت ْع َت ُدوا ِإ َّن َّ َ‬\n      ‫((كل املســلم علــى املســلم حــرا ٌم‬                 ‫ُّ‬           ‫‪ -‬قــال صلــى اهلل عليــه وســلم ‪:‬‬\n      ‫كـ ْـم‬‫وعرضــه)) وقــال عليــه الصــاة والســام ‪((:‬فَ ـ ِإ َّن د َِم َاء ُ‬                              ‫ُ‬          ‫دم ـ ُه وما ُل ـ ُه‬   ‫ُ‬\n      ‫ك ْم‬ ‫ك ُح ْر َمـ ِة َي ْومِ ُكـ ْـم َه َذا ‪ِ ،‬ف َشــهْ ِر ُ‬   ‫اض ُكـ ْـم َحـ َـرا ٌم َع َل ْي ُكـ ْـم َ‬  ‫َوأ َْم َوا َل ُكـ ْـم َوأَعْ َر َ‬\n                                                                                         ‫كـ ْـم َهـ َـذا ))‪.‬‬     ‫َهـ َـذا ‪ِ ،‬ف َب َلدِ ُ‬\n\n\n\n\n      ‫اتهــام املدعــي العــام للمدعــى عليــه بقيامــه بطعــن املجنــي عليــه بــأداة‬\n      ‫حــادة وإصابتــه وطلــب إدانتــه وتعزيــره شــرعا‪ ،‬تبلــغ مركــز الشــرطة‬\n      ‫عــن وجــود شــخص مصــاب إثــر تعرضــه للضــرب يف رأســه بواســطة‬\n      ‫مفتــاح ســيارة ويتهــم املدعــى عليــه (شــقيقه) وقــد قــام املدعــى عليــه‬\n                   ‫بتســليم نفســه‪ ،‬إقــرار املدعــى عليــه مبــا جــاء يف الدعــوى ‪.‬‬\n      ‫‪ -‬ثبــوت اإلدانــة واحلكــم مبــا يلــي ‪ :‬بســجنه ســتة أشــهر مــن تاريــخ إيقافه‬\n\n‫‪205‬‬\n\f‫علــى ذمــة القضيــة‪ ،‬بجلــده مائــة جلــدة مفرقــة علــى دفعتــن متســاويتني‬\n‫كل دفعــة خمســون جلــدة وبــن كل دفعــة وأخــرى مــدة ال تقــل عــن‬\n‫عشــرة أيــام‪ ،‬يؤخــذ عليــه التعهــد بعــدم العــودة ملثــل مــا صــدر منــه‪ ،‬قــرر‬\n‫املدعــي العــام االعتــراض وطلــب االســتئناف بــدون الئحــة وقــرر املدعــى‬\n               ‫عليــه القناعــة‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫ـدي‬\n ‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ ال نبــي بعــده وبعــد فلـ َّ‬\n‫ـاء علــى املعاملــة‬\n                 ‫أنــا ‪ ....‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنـ ً‬\n‫الــواردة إلينــا مــن دائــرة التحقيــق واالدعــاء العــام مبحافظــة األحســاء‬\n‫برقــم ه ق‪1618‬وتاريخ‪1434/02/03‬ه ـ واملقيــدة بهــذه احملكمــة‬\n‫برقم‪34286037‬وتاريخ‪1434/02/04‬ه ـ واحملالــة إلينــا مــن فضيلــة‬\n‫الرئيــس برقــم‪ 3457327‬وتاريــخ ‪1434/02/04‬هـ فتحت اجللســة األولى‬\n‫يــوم االثنــن ‪1434/04/08‬ه ـ الســاعة الثامنــة وفيهــا حضــر املدعــي‬\n‫العــام ‪ ....‬امل َُع ّمــد بالترافــع أمــام احملكمــة طرفنــا مبوجــب خطــاب‬\n‫ســعادة رئيــس دائــرة التحقيــق واالدعــاء العــام مبحافظــة األحســاء ذي‬\n‫ا ‪ :‬بصفتــي‬    ‫الرقــم ‪13415‬والتاريــخ ‪1433/12/01‬ه ـ وقـ ّـرر دعــواه قائ ـ ً‬\n‫مدعي ـ ًا عام ـ ًا يف دائــرة االدعــاء العــام مبحافظــة األحســاء أدعــي علــى‪/‬‬\n‫‪ ، ....‬البالــغ مــن العمــر(‪ ) 36‬عامـ ًا ‪ ،‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم (‪ ، )....‬أوقــف بتاريــخ ‪1433/9/12‬ه ـ وأفرج عنه بالكفالة‬\n‫بتاريخ‪1433/9/14‬ه ـ ‪ ،‬يســكن مبحافظــة األحســاء‪/‬قرية ‪ ........‬إنــه‬\n‫بتاريــخ ‪1433/9/11‬ه ـ تبلــغ مركــز شــرطة محافظــة األحســاء مــن‬\n‫اســتعالمات مستشــفى ‪ .................‬بالهفــوف عــن وجــود شــخص يدعــى‪/‬‬\n\n                                                                                       ‫‪206‬‬\n\f      ‫‪(...‬شــقيق املدعــى عليــه) مصــاب لديهــم إثــر تعرضــه للطعــن يف رأســه‬\n      ‫بواســطة مفتــاح ســيارة ويتهــم بذلــك املدعــى عليــه (شــقيقه) وقــد قــام‬\n      ‫املدعــى عليــه بتســليم نفســه بتاريــخ ‪1433/9/12‬هــ‪ .‬وباالنتقــال إلــى‬\n      ‫موقــع املنــزل ملعاينتــه اتضــح أنــه يقــع بقريــة ال‪ ..‬ومكــون مــن طابقــن‬\n      ‫وقــد لوحــظ بالغرفــة اخلارجيــة وجــود طاولــة وقــد انكســرت أحــد‬\n      ‫قوائمهــا كمــا لوحــظ وجــود بقعتــن دمــاء بســيطة علــى األرض أثبــت‬\n      ‫تقريــر فحــوص حيويــة رقــم(‪ )322‬ايجابيتهــا لــدم ادمــي‪ .‬وبضبــط أقــوال‬\n      ‫املجنــي عليــه املدعــو‪ :... /‬أفــاد أنــه أثنــاء تواجــده مبجلــس منزلهــم رفــق‬\n      ‫شــقيقه ‪ ...‬ونســيبه ‪ ...‬دخــل عليهــم املدعــى عليــه املذكــور ويف يــده‬\n      ‫مفتــاح ســيارته وقــام باســتفزازه ممــا أثــار غضبــه واشــتبك معــه باأليــدي‬\n      ‫وقــام بضربــه مبفتــاح الســيارة علــى رأســه ممــا أدى إلــى اســتقرار‬\n      ‫املفتــاح فيــه وقــد صــدر بحقــه التقريــر الطبــي رقــم(‪)41/27/4/12632‬‬\n      ‫وتاريخ‪1434/9/18‬ه ـ مــن مستشــفى ‪ .................‬املتضمــن جــرح نافــذ‬\n      ‫باجلبهــة أعلــى احلاجــب األيســر بواســطة مفتــاح ســيارة مت اختــراق عظــم‬\n      ‫اجلبهــة وأغلفــة املــخ مــع تهتــك مبقدمــة الفــص األمامــي األيســر للمــخ‬\n      ‫ومــدة الشــفاء ســتة أســابيع مالــم حتــدث مضاعفــات‪ .‬وبضبــط شــهادة‬\n      ‫املدعــو‪ :.... /‬أفــاد أنــه أثنــاء تواجــده مبنــزل والــد زوجتــه‪ ... /‬بقريــة ‪.....‬‬\n      ‫ال مــن‪ ... /‬و‪....‬دخــل‬ ‫بعــد صــاة املغــرب لتنــاول وجبــة اإلفطــار رفــق ك ً‬\n      ‫عليهم املدعى عليه أن اشــتبك مع شــقيقه ‪...‬وعندما قام للتفريق بينهما‬\n      ‫رفــق املوجوديــن شــاهد مفتــاح الســيارة مســتقر ًا يف رأس ‪ ...‬املذكــور‬\n      ‫ولــم يشــاهد ‪...‬وهــو يقــوم بضربــه‪ .‬وبضبــط أقــوال شــقيق املجنــي‬\n      ‫عليــه املدعــو‪ ... /‬و‪ ....‬أفــادوا مبــا أفــاد بــه الشــاهد(‪ . )...‬وباســتجواب‬\n      ‫املدعــى عليــه‪ :‬أقــر بقيامــه بضــرب شــقيقه مبفتــاح ســيارة علــى رأســه‬\n\n\n‫‪207‬‬\n\f‫بســبب خــاف حصــل بينهمــا وصــدق إقــراراه شــرعا بذلــك وقــد أســفر‬\n‫التحقيــق معــه عــن توجيــه االتهــام لــه باالعتــداء بالضــرب وطعــن شــقيقه‬\n‫‪ ...‬يف رأســه بواســطة مفتــاح ســيارته ممــا تســبب يف اصابتــه ‪ ،‬وذلــك‬\n‫لألدلــة والقرائــن التاليــة‪-1 -:‬إقــراره املصــادق عليــه شــرعا املــدون علــى‬\n‫الصفحــة رقــم(‪ )8-7‬املرفــق لفــة رقــم(‪ -2 .)4‬شــهادة املدعــو ‪ .../‬املدونــة‬\n‫علــى الصفحــة رقــم(‪ )12-11‬املرفــق لفــة رقــم(‪ -3 . )1‬مــا جــاء يف إفــادة‬\n‫أشــقاء املدعــى عليــه (‪ )...‬و(‪ )...‬املدونــة علــى الصفحــة رقــم(‪)10-9‬‬\n‫وصفحــة رقــم(‪ )14-13‬املرفــق لفــة رقــم(‪ -4 .)1‬التقريــر الطبــي املرفــق‬\n‫لفــة رقــم(‪ -5 .)31‬تقريــر الفحــوص الوراثيــة املرفــق لفــة رقــم(‪-6.)39‬‬\n‫بــاغ املجنــي عليــه وتوافقــه إجمــاال مــع وقائــع القضيــة املدونــة علــى‬\n‫الصفحــة رقــم(‪ )3-2‬املرفــق لفــة رقــم(‪ .)2‬وبالبحــث عمــا إذا كان لــه‬\n‫ســوابق‪ :‬تبــن عــدم وجــود ســوابق عليــه مســجلة‪ .‬وحيــث إن مــا أقــدم‬\n‫عليــه املذكــور ‪ -‬وهــو بكامــل أهليتــه املعتبــرة شــرع ًا ‪ -‬فعــل محــرم‬\n‫ومعاقــب عليــه شــرع ًا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة‬\n‫تعزيريــة رادعــة وزاجــرة لغيره‪(.‬علمــا بــان احلــق اخلــاص انتهــى بالتنــازل)‬\n‫‪ .‬هكــذا ا َّدعــى ؛ عليــه فقــد حضــر املدعــى عليــه وبعــد التأكــد‬\n‫بعــد هويتــه جــرى عــرض دعــوى املدعــي العــام مــن اتهامــي باالعتــداء‬\n‫بالضــرب وطعنــي شــقيقي ‪ ...‬يف رأســه بواســطة مفتــاح ســيارتي ممــا‬\n‫تســبب بإصابتــه باإلصابــات املوصوفــة يف التقريــر الطبــي املذكــور‬\n‫فصحيــح وذلــك بســبب ســوء تفاهــم بيننــا وقــد انتهــت األمــور بيننــا علــى‬\n‫خيــر إن شــاء اهلل هكــذا أجــاب ثــم جــرى االطــاع علــى جميــع أوراق‬\n‫املعاملــة ومنهــا ‪ :‬التقريــر الطبــي الصــادر مــن مستشــفى ‪.................‬‬\n‫برقــم ‪ 41/27/4/12632‬وتاريــخ ‪1433/09/18‬ه ـ املتضمــن إصابــة‬\n\n\n                                                                                      ‫‪208‬‬\n\f      ‫املجنــي عليــه بجــرح نافــذ باجلبهــة أعلــى احلاجــب األيســر بواســطة‬\n      ‫مفتــاح ســيارة مت اختــراق عظــم اجلبهــة وأغلفــة املــخ مــع تهتــك مبقدمــة‬\n      ‫الفــص األمامــي األيســر للمــخ ومــدة الشــفاء ســتة أســابيع مــا لــم حتــدث‬\n      ‫مضاعفــات وبعرضــه علــى املدعــى عليــه قــال ‪ :‬مــا ورد مــن مــدة الشــفاء‬\n      ‫مبالــغ فيــه وقــد رفعــت شــكوى علــى املستشــفى هكــذا قــرر كمــا‬\n      ‫جــرى االطــاع علــى كــرت ســوابق املدعــى عليــه املتضمــن عــدم وجــود‬\n      ‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبعــد النظــر‬             ‫ســوابق عليــه فبنـ ً‬\n      ‫يف حــال املدعــى عليــه والتأكــد مــن أهليتــه وبعــد دراســة أوراق املعاملــة‬\n      ‫أن املدعــى عليــه أقـ َّـر بدعــوى املدعــي العــام مــن اتهامــه‬            ‫وتأملهــا ومبــا َّ‬\n      ‫باالعتــداء بالضــرب وطعنــه شــقيقه ‪ ...‬يف رأســه بواســطة مفتــاح ســيارته‬\n      ‫ممــا تســبب بإصابتــه باإلصابــات املوصوفــة يف التقريــر الطبــي املذكــور‬\n      ‫(و َل ُت ْف ِسـ ُـدوا ِف‬\n                            ‫أن مــا صــدر منــه مــن احملـ َّـرم شــرع ًا قــال تعالــى‪َ :‬‬          ‫ومبــا َّ‬\n                     ‫(وال َت ْع َتـ ُـدوا ِإ َّن َّ َ‬\n      ‫الل ال ُي ِحـ ُّـب‬                           ‫ض َب ْعـ َـد ِإ ْص َلحِ َهــا ) وقــال تعالــى ‪َ :‬‬       ‫َْ‬\n                                                                                                       ‫ال ْر ِ‬\n      ‫حرام‬\n      ‫ٌ‬         ‫ين ) وقال صلى اهلل عليه وســلم ‪(( :‬كلُّ املســلم على املســلم‬                                        ‫الُ ع َتدِ َ‬\n      ‫كـ ْـم‬\n           ‫‪((:‬ف ـ ِإ َّن د َِم َاء ُ‬\n                                 ‫وعرضــه)) وقــال عليــه الصــاة والســام َ‬                     ‫ُ‬           ‫دم ـ ُه وما ُل ـ ُه‬ ‫ُ‬\n      ‫كـ ْـم َهـ َـذا ‪ِ ،‬ف‬      ‫ك ُح ْر َمـ ِة َي ْومِ ُ‬\n                                                       ‫كـ ْـم َ‬\n                                                              ‫كـ ْـم َحـ َـر ٌام َع َل ْي ُ‬\n                                                                                          ‫اض ُ‬‫َكـ ْـم َو َأ ْع َر َ‬ ‫َو َأ ْم َوال ُ‬\n      ‫كـ ْـم َهـ َـذا )) ممــا يســتوجب تعزيــر املدعــى عليــه‬                      ‫ك ْم َهـ َـذا ‪ِ ،‬ف َبلَدِ ُ‬      ‫َشـ ْـه ِر ُ‬\n      ‫ويتوجــه تخفيــف العقوبــة عليــه النتهــاء احلــق اخلــاص بالتنــازل لــذا كلــه‬\n      ‫وألجــل احلــق العــام حكمــت علــى املدعــى عليــه مبــا يلــي ‪ :‬أوالً‪ /‬ثبــت‬\n      ‫ـدي إدانــة املدعــى عليــه باالعتــداء بالضــرب وطعنــه شــقيقه ‪ ...‬يف رأســه‬                                       ‫لـ َّ‬\n      ‫بواســطة مفتــاح ســيارته ممــا تســبب بإصابتــه باإلصابــات املوصوفــة يف‬\n      ‫التقريــر الطبــي املذكــور وعزرتــه لقــاء ذلــك بســجنه ملــدة ســتة أشــهر‬\n      ‫حتتســب منهــا املــدة التــي أوقــف فيهــا علــى ذمــة القضيــة وبجلــده مائتــي‬\n\n\n‫‪209‬‬\n\f‫جلــدة مفرقــة علــى اربــع دفعــات كل دفعــة خمســون جلــدة وبــن كل‬\n‫دفعــة وأخــرى مــدة ال تقــل عــن عشــرة أيــام ‪ .‬ثانيـ ًا ‪ /‬يؤخــذ عليــه التعهــد‬\n‫بعــدم العــودة ملثــل مــا صــدر منــه وبتــاوة احلكــم علــى الطرفــن وإفهــام‬\n‫املدعــى عليــه بحقــه يف متييــز احلكــم قــرر قناعتــه بــه وطلــب املدعــي‬\n‫العــام رفــع كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم‬\n‫دون الئحــة اعتراضيــة مكتفي ـ ًا مبــا ورد يف الئحــة الدعــوى وأقفلــت‬\n‫اجللســة الســاعة الثامنــة والنصــف وصلــى اهلل وس ـلَّم علــى نبينــا محمــد‬\n                    ‫وعلــى آلــه وصحبــه أجمعــن‪ .‬حــرر يف ‪1434/04/08‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء املكلــف‬\n‫برقــم ‪ 341539919‬وتاريــخ ‪1434/8/13‬ه ـ املقيــدة لــدى احملكمــة‬\n‫برقــم ‪ 341993721‬وتاريــخ ‪1434/8/16‬ه ـ املرفــق بهــا القــرار الصــادر‬\n‫مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ ....‬املســجل برقــم ‪34184279‬‬\n‫وتاريــخ ‪1434/4/10‬ه ـ اخلــاص بدعوى‪/‬املدعــى العــام ضــد‪ ..../‬يف‬\n‫قضيــة اعتــداء وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه ‪ .‬عليــه قررنــا املصادقــة علــى احلكــم بعــد االجــراء االخيــر‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف‬\n                                                                   ‫‪1434/8/22‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                         ‫‪210‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":205,"source_page_end":210,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9ea2ad27ce48a243b03f96f1d4fe75d1ca5bb45486553ec25e8f5c7097b1837f","normalized_text_hash":"eb9897751ff09d9ead0bdd618cedfc133eca723f9c124987a43649316c120d69","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p205-3429077"},{"id":"84ed7dd6-478e-5580-b559-0bf3e816950e","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب والد لولده -إحداث إصابات -جتاوز حد التأديب الشرعي -إقرار املدعى عليه -التعزير بالسجن -صرف النظر عن تطبيق نظام االجتار بالبشر -ضرورة التأكد من حاجة الطفل للرعاية الطبية والنفسية مبا يكفل سامته .","document_number":"3420397","case_number":"33696803","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف مبالحظات عدة أجاب عنها ناظر القضية صدق احلكم من محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/24","year":"1434","subject":"اعتداء -ضرب والد لولده -إحداث إصابات -جتاوز حد التأديب الشرعي -إقرار املدعى عليه -التعزير بالسجن -صرف النظر عن تطبيق نظام االجتار بالبشر -ضرورة التأكد من حاجة الطفل للرعاية الطبية والنفسية مبا يكفل سامته .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 3420397 :‬تاريخه‪1434/01/24 :‬هـ‬\n                         ‫رقم الدعوى‪33696803:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34202447‬تاريخه‪1434/04/30 :‬هـ‬\n\n\n\n      ‫اعتــداء ‪ -‬ضــرب والــد لولــده ‪ -‬إحــداث إصابــات ‪ -‬جتــاوز حــد التأديــب‬\n      ‫الشــرعي ‪ -‬إقــرار املدعــى عليــه ‪ -‬التعزيــر بالســجن ‪ -‬صــرف النظــر عــن‬\n      ‫تطبيــق نظــام االجتــار بالبشــر ‪ -‬ضــرورة التأكــد مــن حاجــة الطفــل‬\n                             ‫للرعايــة الطبيــة والنفســية مبــا يكفــل ســامته ‪.‬‬\n\n\n\n\n      ‫‪ -‬مــا ذكــره الفقهــاء أن الضــرب غيــر املبــرح هــو‪ :‬الــذي ال إســراف فيــه‬\n      ‫‪ ،‬وهــو الــذي يؤلــم ‪ ،‬وال يكســر عظم ـ ًا ‪ ،‬وال يدمــي جســم ًا ‪ ،‬وال يشــق‬\n          ‫جلــد ًا ‪ ( .‬حاشــية ابــن عابديــن ‪ ، 3/190‬إعانــة الطالبــن ‪. ) 4/192‬‬\n      ‫‪ -‬قــال العــز بــن عبدالســام رحمــه اهلل ‪ ( :‬فــإن قيــل إذا كان الصبــي ال‬\n      ‫ا ملصلحــة تأديبه‪،‬‬ ‫يصلحــه إال الضــرب املبــرح فهــل يجــوز ضربــه حتصيـ ً‬\n      ‫قلنــا ‪ :‬ال يجــوز ذلــك ‪ ،‬بــل يجــوز أن يضربــه ضرب ـ ًا غيــر مبــرح ؛ ألن‬\n      ‫الضــرب الــذي ال يبــرح مفســدة ‪ ،‬وإمنــا جــاز لكونــه وســيلة إلــى مصلحــة‬\n      ‫التأديــب ‪ ،‬فــإذا لــم يحصــل التأديــب ســقط الضــرب اخلفيــف ‪ ،‬كمــا‬\n      ‫يســقط الضــرب الشــديد ‪ ،‬ألن الوســائل تســقط بســقوط املقاصــد ) ‪.‬‬\n                                                         ‫قواعــد األحــكام (‪. )103/1‬‬\n\n\n\n\n‫‪211‬‬\n\f‫ادعــى املدعــي العــام علــى املدعــى عليــه بارتكابــه جرميــة االجتــار‬\n‫بالبشــر ‪ ،‬وذلــك بتعذيــب طفلــه القاصــر ‪ ،‬و جتــاوزه حــد التأديــب‬\n‫الشــرعي ‪ ،‬و التســبب يف إصابتــه‪ ،‬حيــث تقــدم أحــد األشــخاص‬\n‫ببــاغ عــن تعــرض ابــن أخيــه للتعذيــب والضــرب مــن قبــل والــده األخ‬\n‫الشــقيق للمبلــغ ‪ ،‬وبســؤال املجنــي عليــه أفــاد بتعرضــه للضــرب مــن قبــل‬\n‫والــده‪ ،‬بــأداة ســلك كهربــاء ‪ ،‬ومباســورة وعالقــة مالبــس حديديــة‬\n‫‪ ،‬وأن اإلصابــات التــي فيــه قــد تســبب بهــا والــده ‪ ،‬وقــد شــاهدت أم‬\n‫الطفــل زوجهــا يضــرب ابنهــا املجنــي عليــه بســلك كهربــاء ‪ ،‬ويســتخدم‬\n‫العصــا واملاســورة وعالقــة املالبــس بضــرب أوالدهــا ‪،‬وأنــه يقــوم بضــرب‬\n‫أطفالهــا منــذ عشــر ســنوات ‪ ،‬وأنهــا حاولــت تخليــص ابنهــا منــه ‪،‬‬\n‫ولــم تســتطع ‪ ،‬وطلــب املدعــي العــام تعزيــر املدعــى عليــه لقــاء مــا جــاء‬\n‫بدعــوى املدعــي العــام ‪ ،‬أقــر املدعــى عليــه مبــا جــاء بدعــوى املدعــي‬\n‫العــام ‪ ،‬وذكــر أن ذلــك كان بســبب غضبــه وأراد بالضــرب تأديــب‬\n‫ولــده ‪ ،‬احلكــم بصــرف النظــر عــن طلــب املدعــي العــام بتطبيــق املــادة‬\n‫(‪ )3‬مــن نظــام مكافحــة االجتــار بالبشــر بحــق املدعــى عليــه ‪ ،‬احلكــم‬\n‫بتعزيــر املدعــى عليــه بالســجن لقــاء ضربــه ابنــه ضرب ـ ًا مبرح ـ ًا جنــم‬\n‫عنهــا اإلصابــة املوصوفــة بالتقريــر الطبــي وأخــذ التعهــد بعــدم العــودة ملــا‬\n‫بــدر منــه ‪ ،‬قنــع املدعــى عليــه باحلكــم ‪ ،‬واملدعــي العــام قــرر اعتراضــه‬\n‫علــى احلكــم مكتفيـ ًا بالئحــة الدعــوى ‪ ،‬عــادت املعاملــة مــن محكمــة‬\n‫االســتئناف مبالحظــات عــدة أجــاب عنهــا ناظــر القضية ـ ـ صدق احلكم‬\n                                                     ‫مــن محكمــة االســتئناف ‪.‬‬\n\n                                                                                       ‫‪212‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بتبــوك وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بتبوك‪/‬املكلــف برقــم ‪ 33696803‬وتاريــخ ‪1433/12/21‬‬\n      ‫ه ـ املقيــدة باحملكمــة برقــم ‪ 332211432‬وتاريــخ ‪ 1433/12/21‬ه ـ‬\n      ‫ففــي يــوم الثالثــاء املوافــق‪ 1434/01/13‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫‪ 12 : 15‬وفيهــا حضــر املدعــي العــام ‪ ... /‬املكلــف باالدعــاء العــام‬\n      ‫مــن قبــل هيئــة التحقيــق واالدعــاء العــام مبنطقــة تبــوك مبوجــب اخلطــاب‬\n      ‫رقــم ‪ 13058‬بتاريــخ ‪ 1433 / 9/ 5‬هـ ـ وحضــر حلضــوره املدعــى عليــه ‪/‬‬\n      ‫‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬فأدعــى قائــا يف‬\n      ‫حتريــر دعــواه أنــه انــه يف يــوم االثنــن املوافــق ‪1433/11/15‬ه ـ بتمــام‬\n      ‫الســاعة السادســة وخمــس وثالثــن دقيقــة مســاء تقــدم املواطــن ‪... /‬‬\n      ‫بشــكوى ملركــز شــرطة ‪ ........‬مفــاده تعــرض ابــن شــقيقه الطفــل ‪/‬‬\n      ‫‪ ...‬تعذيــب والضــرب مــن قبــل والــده املدعــى عليــه ‪ ... /‬وبســماع أقــوال‬\n      ‫املجنــي عليــه الطفــل ‪ ... /‬يبلــغ مــن العمــر (‪ )10‬ســنوات ذكــر بــأن والــده‬\n      ‫قــام بضربــه بــأداة ســلك كهربــاء وانــه اعتــاد علــى ضربــه ألكثــر مــن‬\n      ‫مــره ومــن األدوات التــي يســتخدمها باالعتــداء ماســورة وعالقــة مالبــس‬\n      ‫حديديــة كمــا ذكــر بــأن والــده هــو املتســبب يف إصابتــه باإلصابــات‬\n      ‫املوصوفــة بالتقريــر الطبــي وبســماع أقــوال والــدة الطفــل املواطنــة ‪/‬‬\n      ‫‪ ...‬ذكــرت أن يــوم األحــد املوافــق ‪1433/11/14‬ه ـ وعندمــا كانــت‬\n      ‫نائمــة يف منزلهــم أخبرتهــا ابنتهــا بــأن والدهــا يقــوم بضــرب شــقيقها ‪...‬‬\n      ‫وعندمــا ذهبــت إليهــم شــاهدت زوجهــا املدعــى عليــه ‪ ...‬يقــوم بضــرب‬\n\n‫‪213‬‬\n\f‫ابنهــا بســلك كهربائــي وحاولــت تخليصــه منــه بالقــوة كمــا ذكــرت‬\n‫بأنــه يقــوم بضــرب أطفالهــا منــذ مــا يقــارب عشــر ســنوات وذكــرت بأنــه‬\n‫يســتخدم العصــا واملاســورة وعالقــة املالبــس احلديديــة بضــرب أطفالهــا‬\n‫وباســتجواب املدعــى عليــه رفــض ســماع أقوالــه ورفــض اســتجوابه‬\n‫وطلــب إحالتــه للمحكمــة املختصــة وقــد صــدر التقريــر الطبــي النهائــي‬\n‫بحــق املجنــي عليــه الطفــل ‪ .... /‬رقــم (‪ )420‬وتاريــخ ‪1433/11/15‬ه ـ‬\n‫الصــادر مــن مستشــفى ‪ ....‬ومضمونــة (كدمــات يف العضــد األيســر‬\n‫والكتــف األيســر والظهــر واجلهــة اخللفيــة للســاق األيســر وســحجات يف‬\n‫الظهــر وجــرح يف الــرأس بحوالــي (‪1‬ســم) غيــر واصــل العظــم وأجريــت‬\n‫لــه عمليــة تنظيــف ولــم جتــرى لهــم عمليــة خياطــة بســبب طــول فتــرة‬\n‫اجلــرح وهــو مكشــوف واألداة املســتخدمة صلبــة غيــر حــادة ومــدة‬\n‫الشــفاء املتوقعــة ســبعة أيــام مــا لــم حتــدث مضاعفــات ) وملــا أشــير إليــه‬\n‫أقــرر توجيــه االتهــام للمدعــى عليــه ‪ ...‬بارتــكاب جرميــة االجتــار بالبشــر‬\n‫إلســاءة وذلــك بتعذيــب طفلــة القاصــر ‪ ... /‬وجتــاوزه حــد التأديــب‬\n‫الشــرعي والتســبب بإصابتــه باإلصابــات املوصوفــة بالتقريــر الطبــي‬\n‫املرفــق وجتــاوزه حــد التأديــب الشــرعي وفقــا ملــا تقضــي بــه املــادة الثانيــة‬\n‫مــن نظــام االجتــار باألشــخاص الصــادر بقــرار مجلــس الــوزراء رقــم‬\n‫(‪ )244‬وتاريــخ ‪1430/7/20‬ه ـ وباملوافقــة الســامية رقــم (‪ )40‬وتاريــخ‬\n‫‪1430/7/21‬ه ـ وذلــك لألدلــة التاليــة ‪1‬ت مــا جــاء باقــوال املجنــي عليــه‬\n‫الطفــل ‪ ... /‬املنــوه عنــه املــدون علــى الصفحــات املرفقــة رقــم (‪11‬الــى‬\n‫‪2 )12‬ـ مــا جــاء باقــوال والــده املجنــي عليــه الطفــل ‪ ... /‬املنــوه عنــه املرفــق‬\n‫لفــه رقــم (‪4 )3‬ـ مــا جــاء بالصــور الفوتوغرافيــة بشــأن معاينــة اإلصابــات‬\n‫بالطفــل املنــوه عنــه املرفــق لفــه رقــم (‪ )17‬وحيــث أن مــا أقــدم عليــه‬\n\n\n                                                                                           ‫‪214‬‬\n\f      ‫املدعــى عليــه املذكــور فعــل محــرم شــرعا ومعاقــب عليــه ونظامــا وفيــه‬\n      ‫إخــال باألمانــة وتعــدي حــدود التأديــب الشــرعي لطفــل ال ميلــك الدفــاع‬\n      ‫عــن نفســه لــذا اطلــب مــا يلــي ‪ -1‬إثبــات مــا أســند إليــه‪2 .‬ـ احلكــم عليــه‬\n      ‫اســتنادا للمــادة الثالثــة مــن نظــام االجتــار باألشــخاص الصــادر بقــرار‬\n      ‫مجلــس الــوزراء رقــم (‪ )244‬وتاريــخ ‪1430/7/20‬ه ـ وباملوافقــة الســامية‬\n      ‫رقــم (‪ )40‬وتاريــخ ‪1430/7/21‬ه ـ ‪ .‬وبعــرض دعــوى املدعــي العــام علــى‬\n      ‫املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي العــام صحيــح وأنــا ضربتــه‬\n      ‫بســلك كهربائــي توصيلــة واقصــد من ذلــك تأديبه وكنت غضبان جدا‬\n      ‫ألنــه تكــرر منــه اخلطــأ يف يــوم واحــد ولكنــي أعتــرف أننــي أســرفت يف‬\n      ‫الضــرب ويعلــم اهلل أننــي لــم أقصــد ولــن جتــد يــا شــيخ أب يقســو علــى‬\n      ‫ابنــه هكــذا وال يتألــم وهــي أول مــرة اضربــه بهــذه الطريقــة واآلن نــادم‬\n      ‫علــى مــا فعلــت وأطلــب مــن اهلل ثــم منكــم لــم أشــقائي بأســرتي هكــذا‬\n      ‫أجــاب وبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة املتضمنــة أقــرار‬\n      ‫املدعــى عليــه مبــا نســبه لــه املدعــي العــام يف دعــواه وحيــث أن اإلقــرار‬\n      ‫حجــة علــى صاحبــة مؤاخــذ بــه وقــد جــرى االطــاع علــى التقريــر الطبــي‬\n      ‫رقــم ‪ 420‬بتاريــخ ‪ 1433 / 11 / 15‬هـ ـ الصــادر مــن مستشــفى امللــك‬\n      ‫فهــد بتبــوك ومضمونــه (كدمــات يف العضــد األيســر والكتــف األيســر‬\n      ‫والظهــر واجلهــة اخللفيــة للســاق األيســر وســحجات يف الظهــر وجــرح يف‬\n      ‫الــرأس بحوالــي (‪1‬ســم) غيــر واصــل العظــم وأجريــت لــه عمليــة تنظيــف‬\n      ‫ولــم جتــرى لهــم عمليــة خياطــة بســبب طــول فتــرة اجلــرح وهــو مكشــوف‬\n      ‫واألداة املســتخدمة صلبــة غيــر حــادة ومــدة الشــفاء املتوقعــة ســبعة أيــام‬\n      ‫مــا لــم حتــدث مضاعفــات )أ ‪ .‬هـ ـ وحيــث أن املدعــى عليــه والــد املجنــي‬\n      ‫عليــه ومــن حقــه تأديبــه ولكنــه فــرط يف تأديبــه حيــث إن مــن شــرط‬\n\n\n‫‪215‬‬\n\f‫ضــرب الوالــد لولــده يف واليــة التأديــب أن يكــون الضــرب غيــر مبــرح‬\n‫كمــا هــو مقــرر عنــد الفقهــاء رحمهــم اهلل وغيــر املبــرح الــذي ال إســراف‬\n‫فيــه وهــو الــذي يؤلــم وال يكســر عظم ـ ًا وال يدمــي جســم ًا وال يشــق‬\n‫جلــد ًا (حاشــية ابــن عابديــن ‪ ،190/3‬إعانــة الطالبــن ‪ )192/4‬قــال‬\n‫العــز بــن عبدالســام رحمــه اهلل (فــإن قيــل إذا كان الصبــي ال يصلحــه‬\n‫إال الضــرب املبــرح فهــل يجــوز ضربــه حتصيــا ملصلحــة تأديبــه قلنــا ال‬\n‫يجــوز ذلــك بــل يجــوز أن يضربــه ضربـ ًا غيــر مبــرح ألن الضــرب الــذي ال‬\n‫يبــرح مفســدة وإمنــا جــاز لكونــه وســيلة إلــى مصلحــة التأديــب فــإذا لــم‬\n‫يحصــل التأديــب ســقط الضــرب اخلفيــف كمــا يســقط الضرب الشــديد‬\n‫ألن الوســائل تســقط بســقوط املقاصــد) قواعــد األحــكام يف مصالــح‬\n‫األنــام ‪ 103/1‬وحيــث إن تعذيــب األطفــال الذيــن ال ذنــب لهــم عمــل‬\n‫محــرم ولــه أثــر بالــغ علــى ســلوك الطفــل ونفســيته وحيــث إن مــا ذكــره‬\n‫املدعــي العــام مــن احلكــم علــى املدعــى عليــه اســتنادا للمــادة الثالثــة‬\n‫مــن نظــام االجتــار باألشــخاص الصــادر بقــرار مجلــس الــوزراء رقــم‬\n‫(‪ )244‬وتاريــخ ‪1430/7/20‬ه ـ وباملوافقــة الســامية رقــم (‪ )40‬وتاريــخ‬\n‫‪1430/7/21‬ه ـ ال ينطبــق علــى املدعــى عليــه لكونــه لــم يســتغل ابنــه يف‬\n‫عمــل محــرم أو عمــل إجرامــي كمــا أن أول املــادة املشــار إليهــا بعاليــه‬\n‫وآخرهــا يوحــي بأنهــا تنطبــق علــى مــن يســتغل ســلطته علــى شــخص‬\n‫خــارج عــن واليتــه يف أعمــال محرمــة ومجرمــة شــرعا ونظامــا لــذا فلــم‬\n‫يثبــت لــدي إدانــة املدعــى عليــه باالجتــار باألشــخاص وثبــت لــدي ضــرب‬\n‫املدعــى عليــه ألبنــه ضربــا مبرحــا جنــم عنــه اإلصابــة املوصوفــة بالتقرير‬\n‫الطبــي بعاليــه وقــررت مايلــي أوال ‪ :‬تعزيــر املدعــى عليــه بســجنه ملــدة‬\n‫شــهرين يحتســب منهــا مــدة إيقافــه علــى ذمــة هــذه القضيــة ثانيــا‪ :‬أخــذ‬\n\n\n                                                                                   ‫‪216‬‬\n\f      ‫التعهــد علــى املدعــى عليــه بعــدم العــودة ملــا بــدر منــه وبعــرض احلكــم‬\n      ‫علــى الطرفــن قــرر املدعــى عليــه قناعتــه بــه وأمــا املدعــي العــام فقــد‬\n      ‫قــرر اعتراضــه مكتفي ـ ًا مبــا جــاء يف أوراق املعاملــة عــن تقــدمي الئحــة‬\n      ‫اعتراضيــة وللبيــان حــرر يف ‪1433/1/13‬ه ـ وصلــى اهلل علــى نبينــا‬\n                                               ‫محمــد وعلــى آلــه وصحبــه أجمعــن‪.‬‬\n      ‫احلمــدهلل وحــده وبعــد ففــي هــذا اليــوم الســبت ‪1434/6/3‬ه ـ فتحــت‬\n      ‫اجللســة الســاعة الثامنــة صباحــا وفيهــا جــرى االطــاع علــى املعاملــة‬\n      ‫الــواردة مــن محكمــة االســتئناف بخطــاب فضيلــة رئيســها املســاعد‬\n      ‫رقــم ‪ 34523594‬وتاريــخ ‪1434/5/7‬ه ـ واملقيــدة لــدى احملكمــة برقــم‬\n      ‫‪ 34523594‬وتاريــخ ‪1434/5/15‬ه ـ ووجدتهــا تتضمــن قــرارا مــن‬\n      ‫أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة الثانيــة رقــم ‪34202447‬‬\n      ‫وتاريــخ ‪1434/4/30‬ه ـ ونصــه بعــد املقدمــة ( وبدراســة القــرار وصــورة‬\n      ‫ضبطــه وأوراق املعاملــة لوحــظ مايلــي أوالً‪:‬تضمنــت الدعــوى اتهامــه‬\n      ‫املدعــى عليــه بضــرب طفلــه القاصــر بقصــد التعذيــب ‪ ،‬وأنكــر ذلــك‬\n      ‫يف جوابــه ‪ ،‬وأثبــت احلكــم إدانتــه بضربــه ضرب ـ ًا مبرح ـ ًا جنــم عنــه‬\n      ‫اإلصابــات املذكــورة ‪ ،‬ولــم يوضــح هــل كان ذلــك علــى ســبيل التعذيــب‬\n      ‫كمــا ورد بالدعــوى أو علــى ســبيل التأديــب كمــا ورد يف إجابتــه ‪،‬‬\n      ‫وال بــد مــن مناقشــة ذلــك ‪ ،‬ملعرفــة الوصــف اجلرمــي ‪ ،‬وأهميــة القضيــة‬\n      ‫ثانيـاً‪ :‬لــم يحكــم بــرد طلــب املدعــي العــام محاكمــة املدعــى عليــه علــى‬\n      ‫ضــوء النظــام املشــار إليــه مــادام لــم يثبــت لديــه انطباقــه علــى الواقعــة ‪.‬‬\n      ‫ثالثـاً‪ :‬ظهــر مــن األوراق يف معــرض التحقيقــات ‪ ،‬ومــن التقريــر الطبــي‬\n      ‫ســبق تكــرر ذلــك منــه ‪ ،‬وأنــه لــم يذهــب بــه للمستشــفى ‪ ،‬لعالجــه مــن‬\n      ‫أثــر ضربــه لــه حيــث ورد بالتقريــر أنــه لــم جتــر خياطــة للجــرح بســبب‬\n\n\n‫‪217‬‬\n\f‫طــول فتــرة وقوعــه ‪ ،‬ولــم يناقــش ذلــك ‪ ،‬ويتحقــق منــه ‪ ،‬ومعرفــة ســبب‬\n‫ذلــك‪ ،‬ملــا لــه أثــر يف النظــر واحلكــم ‪ .‬رابع ـاً‪ :‬ورد يف الدعــوى أن آلــة‬\n‫الضــرب للطفــل مــا ســورة وعالقــة مالبــس حديديــة وســلك كهربائــي‬\n‫وعصــا‪ ،‬ولــم يعتــرف يف إجابتــه ســوى بضربــه بالســلك ‪ ،‬ولم يتحقق مما‬\n‫ســوى ذلــك ‪ .‬خامسـاً‪ :‬ورد يف جوابــه أن ضربــه لطفلــه بســبب أنــه تكــرر‬\n‫منــه اخلطــأ يف يــوم واحــد ‪ ،‬ولــم يوضــح ماهيــة ذلــك اخلطــأ‪ .‬سادس ـاً‪:‬‬\n‫املدعــى عليــه صــادق يف جوابــه علــى دعــوى املدعــي العــام ‪ ،‬ومــن ضمنهــا‬\n‫التعذيــب ‪ ،‬فهــل يكــون املدعــى عليــه مقــر ًا بذلــك ‪ ،‬ويتوجــه إثباتــه‬\n‫شــرعاً‪ .‬ســابعاً‪ :‬لــم يشــتمل تســبيب احلكــم علــى إيــراد األســباب املشــددة‬\n‫واملخففــة للعقوبــة التــي يســتحقها املدعــى عليــه ‪ .‬ثامن ـاً‪ :‬لــم يتضمــن‬\n‫احلكــم رأيـ ًا وإيصــاء حيــال الطفــل مــن جهــة حالتــه النفســية والصحيــة‬\n‫والرعائيــة مبــا يكفــل ســامته ‪ ،‬وعــدم معــاودة والــده ملا حصل‪ .‬تاســعاً‪:‬‬\n‫ورد بالتســبيب أن تعذيــب األطفــال عمــل محــرم ممــا يوحــي بــأن الضــرب‬\n‫بقصــد التعذيــب يف نظــر فضيلتــه ‪.‬ويف موضــع آخــر منــه ذكــر أنــه فــرط‬\n‫يف تأديبــه ‪ .‬وهــذا نــوع تناقــض يف التســبيب فيتعــن رفعــه بإثبــات واقــع‬\n‫احلــال كمــا أنــه لــم يشــر لســوابق املدعــى عليــه ومجــال عملــه الوظيفــي‬\n‫‪.‬ملالحظــة ذلــك ‪ ،‬وإحلــاق مــا يجريــه علــى الضبــط والقــرار وصورتــه‬\n‫حســب التعليمــات ‪ .‬واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n‫وصحبــه وســلم ‪ ،‬قاضــي اســتئناف‪ ...‬ختمــه وتوقيعــه ‪ ،‬قاضــي اســتئناف‬\n‫‪ ...‬ختمــه وتوقيعــه‪ ،‬رئيــس الدائــرة ‪ ...‬ختمــه وتوقيعــه ‪ .‬وعليــه أجيــب‬\n‫أصحــاب الفضيلــة وفقهــم اهلل لهــداه عــن املالحظــة األولــى بأنــه ثبــت‬\n‫لــدي إدانــة املدعــى عليــه بضــرب ابنــه ضربـ ًا مبرحـ ًا جتــاوز حــد التأديــب‬\n‫الشــرعي والتأديــب إن جتــاوز حــده الشــرعي صــار عنفــا وتعذيبــا أمــا‬\n\n\n                                                                                      ‫‪218‬‬\n\f      ‫مــا جــاء يف املالحظــة الثانيــة فلوجاهتــه فإننــي قــررت رد طلــب املدعــي‬\n      ‫العــام مبحاكمــة املدعــى عليــه وفــق املــادة الثالثــة مــن نظــام االجتــار‬\n                                 ‫بالبشــر املشــار إليــه يف دعــواه وبذلــك حكمــت ‪.‬‬\n      ‫أمــا مــا جــاء يف املالحظــة الثالثــة والرابعــة فيجــاب عنهــا بــأن مــا جــاء يف‬\n      ‫ذلــك مــن حتقيقــات هــو مــن إفــادة املجنــي عليــه ووالدتــه وهــذا ادعــاء‬\n      ‫ينقصــه اإلثبــات ولــم يثبــت لــدي كمــا أن مــا جــاء يف التقريــر الطبــي‬\n      ‫مــن وجــود جــرح قــدمي يف املجنــي عليــه ال يلــزم منــه أن ذلــك جــراء مالقيــه‬\n      ‫مــن ضــرب املدعــى عليــه لــه أمــا مــا جــاء يف املالحظــة اخلامســة فأجيــب‬\n      ‫مشــايخي حفظهــم اهلل عنهــا بأنــه لــم يظهــر لــي أهميــة معرفــة اخلطــأ من‬\n      ‫عدمــه ألن مــا قــام بــه املدعــى عليــه جتــاوز حــد التأديــب علــى اخلطــأ أمــا‬\n      ‫مــا جــاء يف املالحظــة السادســة فيجــاب عنــه أن التأديــب إذا جتــاوز حــده‬\n      ‫ـداء‬\n        ‫الشــرعي صــار عنفـ ًا وتعذيبـ ًا وهــذا بخــاف مــا إذا قصــد تعذيبــه ابتـ ً‬\n      ‫لــذا فإنــه جــرى منــي إثبــات إدانتــة املدعــى عليــه بضربــه البنــه ضرب ـ ًا‬\n      ‫مبرح ـ ًا جتــاوز بــه احلــد الشــرعي للتأديــب وذلــك ألنــه ثبــت عنــدي أنــه‬\n      ‫أراد تأديبــه ولكنــه فــرط فتجــاوز فصــار تأديبــه تعذيبـ ًا أمــا ماجــاء يف‬\n      ‫املالحظــه الســابعة فأجيــب أصحــاب الفضيلــة رعاهــم اهلل بأني ذكرت‬\n      ‫يف تســبيب احلكــم بــأن املدعــى عليــه والــد املجنــي عليــه لــذا فــإن رابطــة‬\n      ‫األبــوة تقتضــي التخفيــف علــى األب ولكــون زيــادة ســجنه قــد تكــون‬\n      ‫بــه مضيعــة البنــه وألســرته فاقتضــت املصلحــة العامــة التخفيــف عليــه‬\n      ‫وألن لــم شــمل األســرة بعائلهــا ملقصــد يحــث عليــه الشــارع الكــرمي وملــا‬\n      ‫تضمنتــه املعاملــة مــن تنــازل عــن احلــق اخلــاص ممــا جعلنــي أرى التخفيــف‬\n      ‫عــن املدعــى عليــه أمــا مــا جــاء يف املالحظــة الثامنــة فأجيــب أصحــاب‬\n      ‫الفضيلــة بــأن الطفــل لــم يحضــر لــدي يف مجلــس احلكــم ولــم أعــرف‬\n\n\n‫‪219‬‬\n\f‫مــدى تأثــره النفســي مــن عدمــه فرأيــت أنــه الوجــه باإليصــاء بعالجــه‬\n‫وهــو لــم يحضــر ولــم يرفــق باملعاملــة أي تقريــر طبــي يفيــد بحاجتــه‬\n‫لرعايــة خاصــة أو أنــه يعانــي مــن حالــة نفســية جــراء ضــرب والــده لــه‬\n‫أمــا مــا جــاء يف املالحظــة التاســعة فأجيــب أصحــاب الفضيلــة وفقهــم‬\n‫اهلل لــكل خيــر بــأن مــن فــرط يف التأديــب صــار تأديبــه تعنيفـ ًا وتعذيبـ ًا‬\n‫ـداء انتقام ـ ًا منــه مثــا فاألمــر‬\n                                   ‫وهــذا بخــاف مالــو قصــد تعذيبــه ابتـ ً‬\n‫غيــر متناقــض واحلــال مــا ذكــر كمــا أنــه ليــس للمدعــى عليــه ســوابق‬\n‫حتــى تتــم اإلشــارة إليهــا وال حاجــة ظاهــرة لــدي يف معرفــة مجــال عمــل‬\n‫املدعــى عليــه ممــا يؤثــر يف احلكــم هــذا مــا متــت اإلجابــة واهلل أســأل‬\n‫ملشــايخي الفضــاء التوفيــق والســداد وأن يرينــا احلــق حقــا ويرزقنــا‬\n‫اتباعــه والباطــل باطــا ويرزقنــا اجتنابــه هــذا ماجــرى إحلاقــه بضبطــه‬\n‫وســيجري التهميــش بــه علــى القــرار ومــن ثــم بعــث املعاملــة حملكمــة‬\n‫االســتئناف حســب التعليمــات وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n                 ‫نبينــا محمــد وعلــى آلــه وصحبــه وحــرر يف ‪1434/6/3‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلزائيــة‬\n‫الثانيــة يف محكمــة االســتئناف مبنطقــة تبــوك علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة بتبــوك برقــم ‪34523594‬وتاريــخ‬\n‫‪1434/6/7‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة الشــيخ ‪ ...‬برقــم‬\n‫‪ 3420397‬وتاريــخ ‪ 1434/1/24‬اخلــاص بدعــوى املدعــي العــام ضــد‬\n‫‪ ...‬يف قضيــة االعتــداء بالضــرب وتعذيــب طفــل‪ ،‬علــى النحــو املوضــح‬\n‫يف القــرار واملتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪.‬‬\n‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة ومــا أحلقــه فضيلتــه‬\n‫جواب ـ ًا علــى قــرار الدائــرة رقــم ‪ 34202447‬وتاريــخ ‪1434/4/30‬ه ـ‬\n\n\n                                                                                     ‫‪220‬‬\n\f      ‫قررنــا املصادقــة علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                                   ‫محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪221‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":211,"source_page_end":221,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"12bdadb0323b43e93d4ac4f7a6e5f1c4801d790f687d6beee95993ab0b335472","normalized_text_hash":"a4e240485737ca71c31bbb77e224090dce9ab9b872b8326333e5b4fc5b749d2e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p211-3420397"},{"id":"890dd5b8-273e-54e0-8c8d-511d2bb77103","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -موظف حكومي -مرض املدعى عليه النفسي - عدم مسئولية املدعى عليه جنائي ا-عدم استحقاق املدعي العام ما يدعيه ضد املدعى عليه .","document_number":"3458963","case_number":"34105002","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/09","year":"1434","subject":"اعتداء -ضرب -موظف حكومي -مرض املدعى عليه النفسي - عدم مسئولية املدعى عليه جنائي ا-عدم استحقاق املدعي العام ما يدعيه ضد املدعى عليه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 3458963 :‬تاريخه‪1434/03/09 :‬هـ‬\n                          ‫رقم الدعوى‪34105002:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 34209372‬تاريخه‪1434/05/08 :‬هـ‬\n\n\n\n      ‫اعتــداء ‪ -‬ضــرب ‪ -‬موظــف حكومــي ‪ -‬مــرض املدعــى عليــه النفســي ‪-‬‬\n      ‫عــدم مســئولية املدعــى عليــه جنائي ًا‪-‬عــدم اســتحقاق املدعــي العــام مــا‬\n                                                     ‫يدعيــه ضــد املدعــى عليــه ‪.‬‬\n\n\n\n\n      ‫‪-‬قولــه صلــى اهلل عليــه وســلم ( رفــع القلــم عــن ثالثــة النائــم حتــى‬\n         ‫يســتيقظ وعــن الصبــي حتــى يشــب وعــن املعتــوه حتــى يعقــل ) ‪.‬‬\n\n\n\n\n      ‫‪ -‬ادعــى املدعــي العــام علــى املدعــى عليــه بالقيــام بالتعــدي بالضــرب‬\n      ‫علــى مديــر احلقــوق العامــة باحملافظــة أثنــاء تأديته عملــه ‪ ،‬ورد للدوريات‬\n      ‫األمنيــة عــن قيــام املدعــى عليــه باالعتــداء بالضــرب بآلــة تخــرمي األوراق‬\n      ‫علــى موظــف حكومــي أثنــاء تأديــة عملــه وشــهد الشــهود بذلــك ‪ ،‬وطلب‬\n      ‫املدعــي العــام تعزيــر املدعــى عليــه ‪ ،‬أثبــت التقريــر الطبــي أن املدعــى‬\n      ‫عليــه مصــاب مبــرض الفصــام العقلــي الزورانــي ( اضطهــادي) وهــو غيــر‬\n      ‫مســؤول عــن تصرفاتــه ‪ ،‬حضــر شــقيق املدعــى عليــه والتــزم بحفظــه‬\n      ‫وعــدم تركــه يراجــع الدوائــر احلكوميــة إال مبعيتــه انتهــى احلــق اخلــاص‬\n      ‫بالتنــازل ‪ ،‬احلكــم بعــدم اســتحقاق املدعــي العــام ملــا يدعــي بــه ضــد‬\n\n‫‪227‬‬\n\f‫املدعــى عليــه ‪ ،‬قــرر املدعــي العــام اعتراضــه علــى احلكــم مكتفي ـ ًا‬\n          ‫بالئحــة الدعــوى ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫اجلزائيــة‬\n   ‫ّ‬        ‫احلمــد هلل وحــده وبعــد فلــدي أنــا د‪ ........‬القاضــي يف احملكمــة‬\n‫باالحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة يف محافظــة االحســاء برقــم ‪ ....‬وتاريــخ ‪ ...‬املقيــدة باحملكمــة‬\n‫برقــم ‪ .....‬وتاريــخ ‪.....‬حضــر املدعــي العــام ‪ ....‬وادعــى ضــد ‪ ....‬الســعودي‬\n‫بالســجل املدنــي رقــم (‪ )....‬قائــا انــه بتاريــخ ‪ .....‬ورد لرجــال الدوريــات‬\n‫االمنيــه كتــاب مديــر قســم أمــن احملافظــة املبنــي علــى توجيــه ســمو‬\n‫محافــظ االحســاء علــى احملضــر املعــد مــن قبــل املجنــي عليــه واملتضمــن‬\n‫إيقــاف املدعــى عليــه وذلــك علــى إثــر اعتــداءه بالضــرب بآلــة تخــرمي‬\n‫األوراق علــى موظــف حكومــي يدعــى ‪ ....‬أثنــاء تأديــة عملــه وبضبــط‬\n‫أقــوال املبلــغ ‪ ...‬بــودي أفــاد انــه اثنــاء مراجعــة املدعــى عليــه بشــان معاملــه‬\n‫لــه لديهــم وإفهامــه باإلجــراءات املتعلقــة بهــا أخــذ يتلفــظ بعبــارات تــدل‬\n‫علــى أنــه يف غيــر حالتــه الطبيعيــة ومــن ثــم قــام بالتهجــم عليــه وضربــه‬\n‫بآلــه تخــرمي األوراق وبضبــط شــهادة الشــهود وهــم ‪ ....‬و ‪ .....‬أفــادا بــان‬\n‫املدعــى عليــه كان يناقــش مديــر احلقــوق العامــة وهــو املبلــغ (املجنــي‬\n‫عليــه) موضــوع املعاملــه كانــت لديهــم واشــتد النقــاش وقــام املدعــى‬\n‫عليــه بأخــذ لوحــة أســماء كانــت علــى الطاولــة وآلــه تخــرمي األوراق‬\n‫ورميهــا علــى املبلــغ (املجنــي عليــه) وباســتجواب املدعــى عليــه أقــر‬\n‫بقيامــه باالعتــداء علــى املبلــغ وذلــك برمــي لوحــة االســماء كانــت علــى‬\n‫الطاولــة ورمــي آلــه تخــرمي األوراق وقــد ورد خطــاب مديــر مستشــفى‬\n\n                                                                                            ‫‪228‬‬\n\f      ‫الصحــة النفســية رقــم (‪ )......‬وتاريــخ ‪ .....‬املتضمــن أنــه بعرضــه علــى‬\n      ‫اللجنــة الطبيــة النفســية تبــن أن لــدى املدعــى عليــه فصــام عقلــي زوراني‬\n      ‫(اضطهــادي) ومريــض الســكر وقــد رأت بــأن املذكــور غيــر مســئول‬\n      ‫عــن تصرفاتــه يف القضيــة احلاليــة ويحتــاج الــى التنــومي باملستشــفى لدينــا‬\n      ‫فتــرة حلــن اســتقرار حالتــه ونوصــي باإلســراع يف إنهــاء قضيتــه ليتــم‬\n      ‫رفــع اخلفــارة عنــه حلــن إدراجــه كمريــض لدينــا يف البرنامــج العالجيــة‬\n      ‫وقــد اســفر التحقيــق عــن توجيــه االتهــام لــه بالقيــام بالتهجــم واالعتــداء‬\n      ‫بالضــرب علــى مديــر احلقــوق العامــه مبكتبــه مبقــر محافظــه االحســاء‬\n      ‫اثنــاء تأديــة علميــه وذلــك لألدلــة والقرائــن التاليــة ‪1‬ـ اقــراره املنــوه عنــه‬\n            ‫واملدونــة علــى الصفحــه رقــم (‪ )11-9‬املرفــق علــى اللفــه رقــم (‪)2‬‬\n      ‫‪ -2‬إقــرار الشــهود املدونــه علــى الصفــة رقــم (‪ )16‬املرفــق علــى لفــه‬\n      ‫رقــم(‪ )2‬والصفحــة رقــم(‪ )2‬املرفــق لفــه رقــم(‪3)1‬ـ أقــوال املجنــي عليــه‬\n      ‫املدونــه علــى الصفحــه رقــم(‪ )15-13‬املرفــق لفــه رقــم(‪ -4)2‬احملضــر‬\n      ‫املعــد مــن قبــل املوظف(املجنــي عليــه ) املرفــق لفــه رقم(‪)4‬وببحــث‬\n      ‫ســوابقه تبــن خلــو ســجله مــن الســوابق وحيــث مــا اقــدم عليــه املدعــى‬\n      ‫عليــه وهــو بكامــل أهليتــه املعتبــره شــرع ًا فعــل محــرم ومعاقــب عليــه‬\n      ‫شــرع ًا اطلــب اثبــات مــا اســند اليــه واحلكــم عليــه بعقوبــة تعزيريــه‬\n      ‫تزجــره وتــردع غيره(علم ـ ًا بــان احلــق اخلــاص انتهــى بالتنــازل) وبتصفــح‬\n      ‫اوراق املعاملــة وجــد علــى اللفــه (‪ )41‬تقريــر طبــي صــادر مــن اللجنــة‬\n      ‫الطبيــة مــن قبــل مستشــفى الصحــة النفســية باالحســاء رقــم ‪ ....‬وتاريــخ‬\n      ‫‪ .....‬ونصــه (وبعرضــه علــى اللجنــة الطبيــة النفســية تبــن أنــه هــادئ ـ‬\n      ‫متعــاون ـ كالمــه مفهــوم ـ مزاجــه معتــدل ـ اليــزال يعانــي مــن بعــض‬\n      ‫األفــكار االضطهاديــة ومســتبصر جزئيــا بحالتــه والتشــخيص فصــام‬\n\n\n‫‪229‬‬\n\f‫عقلــي زورانــي (اضطهــادي) ‪ +‬مــرض الســكري والــرأي املذكــور غيــر‬\n‫مســؤول عــن تصرفاتــه يف القضيــة احلاليــة ويحتــاج الــى التنــومي لدينــا‬\n‫لفتــرة حلــن اســتقرار حالتــه ونوصــي باالســراع يف انهــاء قضيتــه ليتــم‬\n‫رفــع اخلفــارة عنــه حتــى ميكــن ادراجــه كمريــض عــادي باملستشــفى‬\n‫حيــث أن القيــود عليــه تزيــد مــن افــكار ضالالتــه االضطهاديــة جتــاه‬\n‫الغيــر وكان حاضــرا شــقيق املدعــى عليــه املدعــو‪ ...‬الســعودي بالســجل‬\n‫املدنــي رقــم (‪ )...‬وقــرر قائــا ان شــقيقي ‪ ...‬مريــض نفســي منــذ عــدة‬\n‫ســنوات وان اتعهــد لديكــم بحفظــه وعــدم تركــه يراجــع الدوائــر‬\n‫احلكوميــة اال وانــا معــه علمــا بأنــه شــقيقي االكبــر ووالــدي متــويف لــذا‬\n‫وبعــد ســماع الدعــوى وحيــث طلــب املدعــي العــام مجــازات املدعــى عليــه‬\n‫لقــاء اعتدائــه علــى موظــف حكومــي مبقــر عملــه وحيــث ان التقريــر‬\n‫الطبــي يثبــت بــأن املدعــى عليــه غيــر مســؤول عــن تصرفاتــه اجلنائيــة وان‬\n‫شــقيقه قــد التــزم لدينــا باحلفــاظ عليــه وعــدم تركــه وملــا ورد يف الشــرع‬\n‫مــن ان املجنــون ال يؤاخــذ علــى فعلــه ولقولــه صلــى اهلل عليــه وســلم (رفــع‬\n‫القلــم عــن ثالثــة عــن النائــم حتــى يســتيقظ وعــن الصبــي حتــى يشــب‬\n‫وعــن املعتــوه حتــى يعقــل ) وان احلــق اخلــاص قــد انتهــى بالتنــازل لــذا فقــد‬\n‫حكمــت بعــدم اســتحقاق املدعــي العــام ملــا يدعــي بــه ضــد املدعــى عليــه‬\n‫‪ ....‬كمــا ثبــت لــدي التــزام ‪ .....‬باحملافظــة علــى شــقيقه ‪ ...‬وعــدم تركــه‬\n‫يراجــع الدوائــر احلكوميــة اال مبعيتــه وبعرضــه اعتــرض عليــه املدعــي‬\n‫العــام وطلــب رفعــه حملكمــة االســتئناف مكتفيــا مبــا جــاء يف دعــواه‬\n‫عــن تقــدمي الئحــة اعتراضيــة كمــا قــرر شــجاع قناعتــه باحلكــم وبــاهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n                                                                ‫يف‪1434/3/9‬ه ـ‬\n\n\n                                                                                        ‫‪230‬‬\n\f      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء برقــم ‪....‬‬\n      ‫وتاريــخ ‪ .....‬املقيــدة لــدى احملكمــة برقــم ‪ .....‬وتاريــخ ‪ .....‬املرفــق بهــا‬\n      ‫القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ د‪ ....‬املســجل‬\n      ‫برقــم ‪ ....‬وتاريــخ ‪ .....‬اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪ ...../‬يف قضيــة‬\n      ‫االعتــداء بالضــرب وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n      ‫ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n      ‫املصادقــه علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                            ‫وصحبــه وســلم حــرر يف‪.....‬‬\n\n\n\n\n‫‪231‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":227,"source_page_end":231,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3e948c4060d60ad16a5e99df91be6ece96fb5161dcacb7d5e15cb31b09ce058b","normalized_text_hash":"0a84dfbeebbb1a12b168239231794d2391992decc1d5a9e090a8f6dbf2906404","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p227-3458963"},{"id":"7f594af1-8097-57f8-8217-43565b41c5e7","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -إشهار ساح ناري بقصد التهديد -االعتداء على زوجة بالضرب وإصابتها -عدم تقدمي املدعي العام بينة على دعواه -صرف النظر عن دعوى املدعي العام.","document_number":"34570621","case_number":"34108815","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/04","year":"1434","subject":"اعتداء -ضرب -إشهار ساح ناري بقصد التهديد -االعتداء على زوجة بالضرب وإصابتها -عدم تقدمي املدعي العام بينة على دعواه -صرف النظر عن دعوى املدعي العام.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34570621 :‬تاريخه‪1434/03/04:‬هـ‬\n                    ‫رقم الدعوى‪34108815:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n        ‫‪ 34199274‬تاريخه‪1434/04/28 :‬هـ‬\n\n\n\n‫اعتــداء ‪ -‬ضــرب ‪ -‬إشــهار ســاح نــاري بقصــد التهديــد ‪ -‬االعتــداء علــى‬\n‫زوجــة بالضــرب وإصابتهــا ‪ -‬عــدم تقــدمي املدعــي العــام بينــة علــى دعــواه‬\n                                   ‫‪ -‬صــرف النظــر عــن دعــوى املدعــي العــام‪.‬‬\n\n\n\n\n                  ‫‪ -‬ما ذكره أهل العلم (أن األصل يف اإلنسان السالمة)‬\n\n\n\n\n‫ادعــى املدعــي العــام علــى املدعــى عليــه بإشــهار الســاح علــى زوجتــه و‬\n‫تهديدهــا وضربهــا وإحــداث إصابــات بهــا ‪ ،‬و طلــب املدعــي العــام تعزيــر‬\n‫املدعــى عليــه لقــاء مــا نســب إليــه ‪ ،‬أنكــر املدعــى عليــه مــا جــاء بدعــوى‬\n‫املدعــي العــام ‪ ،‬بطلــب البينــة مــن املدعــي العــام عــن دعــواه أحضــر‬\n‫شــاهد ًا ولــم يشــهد بصحــة الواقعــة بــل شــهد علــى احملضــر ‪ ،‬مت االطــاع‬\n‫علــى التقريــر الطبــي ومحضــر املواجهــة ‪ ،‬احلكــم بصــرف النظــر عــن‬\n‫دعــوى املدعــي العــام ضــد املدعــى عليــه ‪ ،‬اقتنــع املدعــى عليــه باحلكــم‬\n‫و املدعــي العــام قــرر اعتراضــه علــى احلكــم بالئحــة ‪ ،‬صــدق احلكــم‬\n                                                   ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n                                                                                       ‫‪232‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ .....‬وتاريــخ ‪ ...‬املقيــدة‬\n      ‫باحملكمــة برقــم ‪ ....‬وتاريــخ ‪ ...‬ففــي يــوم األحــد املوافق‪.....‬افتتحــت‬\n      ‫اجللســة الســاعة ‪ 11 : 00‬وفيهــا حضــر املدعــي العــام ‪ ....‬وادعــى علــى‬\n      ‫احلاضــر معــه يف املجلــس الشــرعي ‪ ......‬ســعودي بالســجل املدنــي رقــم‬\n      ‫(‪ )....‬قائــا يف دعــواه عليــه إننــي أتهمــه بتاريــخ ‪ .....‬بإشــهار ســاح نــاري‬\n      ‫بقصــد تهديــد زوجتــه بــه واإلعتــداء عليهــا بالضــرب وإحــداث إصابــة‬\n      ‫بهــا وذلــك لألدلــة والقرائــن املســرودة مبلــف القضيــة أطلــب إثبــات‬\n      ‫مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة علمــا بــان احلــق اخلــاص‬\n      ‫انتهــى بالتنــازل هــذه دعــواي وبعــرض دعــوى املدعــي العــام علــى املدعــي‬\n      ‫عليــه أجــاب قائــا مــا ذكــره املدعــي العــام يف دعــواه غيــر صحيــح هــذه‬\n      ‫إجابتــي وبســؤال املدعــي العــام عــن بينتــه قــال أطلــب مهلــة إلحضارهــا‬\n      ‫هكــذا أفــاد وعليــه رفعــت اجللســة لذلــك ويف يــوم اإلثنــن املوافــق‪......‬‬\n      ‫افتتحــت اجللســة وفيهــا حضــر املدعــي العــام واملدعــى عليــه وبســؤال‬\n      ‫املدعــي العــام عــن بينتــه أحضــر للشــهادة وادائهــا العريــف يف الدوريــات‬\n      ‫االمنيــه ملكــة املكرمــة ‪ .....‬ســعودي اجلنســية مبوجــب ســجل مدني رقم‬\n      ‫(‪ )....‬وبســؤاله عمــا لديــه مــن شــهادة شــهد قائــا بأنــه وردنــي تكليــف‬\n      ‫مــن غرفــة العمليــات حيــث وردهــم بــاغ بوجــود حالــة ســوء تفاهــم ومت‬\n      ‫ذهابــي للموقــع ووجــدت املشــتكية وجــرى منــي تدويــن شــكواها‬\n      ‫مبحضــر تنفيــذ املهمــة وبعدهــا ســلمت احملضــر لشــرطة ‪ ..........‬هــذه‬\n\n‫‪233‬‬\n\f‫شــهادتي وبعــرض الشــاهد وشــهادته علــى املدعــى عليــه أجــاب قائــا‬\n‫أمــا الشــاهد فــا أعرفــه وأمــا الشــهادة فــا أعلــم عنهــا شــي هــذه‬\n‫إجابتــي وبســؤال املدعــي العــام هــل لديــك زيــادة بينــه قــال مــا ورد يف‬\n‫التقريــر الطبــي املتضمــن إصابــة املجنــي عليهــا باصابــات قــدرت مــدة‬\n‫الشــفاء يومــان وكذلــك مــا جــاء يف محضــر املواجهــة املتضمــن كالم‬\n‫املجنــي عليهــا بثقــة بينمــا كالم املدعــى عليــه مرتبــكا وليــس لــدي‬\n‫ســوى ذلــك هكــذا أجــاب وبعــرض ذلــك علــى املدعــى عليــه قــال أمــا‬\n‫التقريــر الطبــي فــا أعلــم عنــه شــيء ولــم أضربهــا نهائيــا أمــا مــا ذكــره‬\n‫يف محضــر املواجهــة فغيــر صحيــح حيــث لــم أكــن مرتبــكا وليــس‬\n‫هنــاك مــا يدعــوا إلرتباكــي ألنــي لــم أخطــىء هكــذا أفــاد فبعدمــا‬\n‫ســلف مــن الدعــوى واإلجابــة وبعــد اإلطــاع علــى محضــر القبــض‬\n‫واإلســتجواب ومحضــر تنفيــذ املهمــة وإلنــكار املدعــى عليــه جميــع مــا‬\n‫نســب إليــه لعــدم تقــدمي املدعــي العــام بينــة علــى دعــواه وخللــو صحيفتــه‬\n‫مــن الســوابق ممــا يــدل علــى حســن ســلوكه وألن األصــل يف اإلنســان‬\n‫الســامة ملــا ســبق كلــه فقــد صرفــت النظــر عــن دعــوى املدعــي العــام‬\n‫هــذا مــا ظهــر لــي وبــه حكمــت وبعــرض ذلــك علــى املدعــي عليــه قــرر‬\n‫القناعــة واملدعــي العــام قرراالعتــراض بالئحــة وأفهــم بنظــام اإلعتــراض‬\n‫وســلم صــورة مــن احلكــم لتقــدمي الئحتــه االعتراضيــه خــال ثالثــن‬\n‫يومــا‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n‫وســلم ‪ .‬حــرر يف ‪ .....‬احلمــد هلل وحــده والصــاة والســام علــى مــن ال‬\n‫نبــي بعــده وبعــد ‪ :‬فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة الثالثــة‬\n‫مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة‬\n‫الــواردة إلينــا شــفع خطــاب فضيلــة رئيــس احملكمــة اجلزائيــة مبكــة‬\n\n\n                                                                                      ‫‪234‬‬\n\f      ‫املكرمــة رقــم ‪ .....‬وتاريــخ ‪ ....‬املشــتملة علــى القــرار الصــادر مــن فضيلــة‬\n      ‫الشــيخ‪ ..... /‬القاضــي باحملكمــة اجلزائيــة مبكــة املكرمــة املــؤرخ يف‬\n      ‫‪ ....‬واملســجل بعــدد ‪ .....‬املتضمــن دعــوى املدعــي العــام ضــد‪ .... /‬املتهــم‬\n      ‫بإشــهار ســاح نــاري بقصــد تهديــد زوجتــه بــه واالعتــداء عليهــا بالضــرب‬\n      ‫وإحــداث إصابــة بهــا احملكــوم فيــه مبــا ّدون بباطــن القــرار وبدراســة‬\n      ‫القــرار وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت املوافقــة علــى‬\n      ‫احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                                    ‫وســلم ‪.‬‬\n\n\n\n\n‫‪235‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":232,"source_page_end":235,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2225d8a0c5fcd59b541615aa43b61caf25a88e6e36e254993a8f45a0b43d7ac8","normalized_text_hash":"9ee32bd6e05ceaf02cf20adab90cdabc8f4c1cbbd32c966cdef29e2c19b34eae","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p232-34570621"},{"id":"683375a1-ab97-5020-b0f0-d3440f494f33","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -خلوة محرمة -تع د لفظي -محاولة تهريب - تهديد بالقتل -تعزير بالسجن واجللد.","document_number":"3461835","case_number":"34109074","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/14","year":"1434","subject":"اعتداء -ضرب -خلوة محرمة -تع د لفظي -محاولة تهريب - تهديد بالقتل -تعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 3461835 :‬تاريخه‪1434/03/14:‬هـ‬\n                    ‫رقم الدعوى‪34109074:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34268518‬تاريخه‪1434/07/15 :‬هـ‬\n\n\n\n‫اعتــداء ‪ -‬ضــرب ‪ -‬خلــوة محرمــة ‪ -‬تعـ ٍّـد لفظــي ‪ -‬محاولــة تهريــب ‪-‬‬\n                         ‫تهديــد بالقتــل ‪ -‬تعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n                               ‫القاعدة الفقهية ( اإلقرار حجة شرعية ) ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام علــى املدعــى عليهــم األول و الثاني باالختالء احملرم‬\n‫‪ ،‬وهــروب املدعــى عليهــا الثانيــة ‪ ،‬وقيــام املدعى عليهــا الثالثة باالعتداء‬\n‫علــى رجــال الهيئــة بالضــرب ‪ ،‬و التســبب يف إصابتــه أحدهــم‪ ،‬و تهريــب‬\n‫املدعــى عليهــا الثانيــة ‪ ،‬و التســتر عليهــا ‪ ،‬و حتريضهــا ‪ ،‬و تضليــل جهــة‬\n‫التحقيــق ‪ ،‬و املدعــى عليــه الرابــع بتهديــد الفرقــة القابضــة بالقتــل‪ ،‬و‬\n‫التعــدي بألفــاظ بذيئــة ‪ ،‬ونتــف شــعرات مــن حليــة أحــد أعضــاء الهيئــة ‪،‬‬\n‫حيــث شــاهدت الهيئــة ســيارة مظللــة بالكامــل ‪ ،‬وقد وضع (الشمســية)‬\n‫علــى الزجــاج األمامــي ‪ ،‬وبالتأكــد مــن وضعيتهــا ‪ ،‬اتضــح أن الســيارة‬\n‫بقيــادة املدعــى عليــه األول ‪ ،‬وبصحبتــه املدعــى عليهــا الثانيــة ‪ ،‬يف‬\n‫حالــة اختــاء محرمــة‪ ،‬وأثنــاء اصطحــاب املدعــى عليــه األول ‪ ،‬حضــرت‬\n‫املدعــى عليهــا الثالثــة ‪ ،‬و املدعــى عليــه الرابــع‪ ،‬واعتديــا علــى عضــو‬\n‫الهيئــة ‪ ،‬وحــاوال تهريــب املدعــى عليهــا الثانيــة ‪ ،‬وقامــت املدعــى عليهــا‬\n                                                                                    ‫‪236‬‬\n\f      ‫الثالثــة بضــرب عضــو الهيئــة بحجــر ‪ ،‬وقامــت املدعــى عليهــا الثانيــة‬\n      ‫بالهــروب ‪ ،‬وحــاول املدعــى عليــه الرابــع إشــغال الفرقــة القابضــة عــن‬\n      ‫املدعــى عليــه األول ‪ ،‬كمــا قامــت املدعــى عليهــا الثانيــة بالصــراخ‬\n      ‫والتهديــد بالقتــل والتلفــظ البــذيء‪ ،‬و طلــب املدعــي العــام تعزيرهــم‬\n      ‫لقــاء ذلــك وتشــديد العقوبــة علــى املدعــى عليهــا الثالثــة و املدعــى عليــه‬\n      ‫الرابــع لقــاء اعتدائهــم علــى عضــو الهيئــة اســتناد ًا لتعميــم ســمو وزيــر‬\n      ‫الداخليــة بذلــك‪ ،‬أقــر املدعــى عليهــم مبــا جــاء بدعــوى املدعــي العــام‬\n      ‫إال املدعــى عليــه الرابــع أنكــر نتــف شــعر حليــة أحــد أعضــاء الهيئــة ‪،‬‬\n      ‫قضــت احملكمــة بتعزيــر املدعــى عليهــم األول و الثانيــة و الثالثــة باجللــد‬\n      ‫لقــاء مــا نســب إليهــم ‪ ،‬واحلكــم بتعزيــر املدعــى عليــه الرابــع بالســجن و‬\n      ‫اجللــد لقــاء مــا نســب إليــه ‪ ،‬قنــع املدعــى عليهــم باحلكــم ‪ ،‬وقــرر املدعــي‬\n      ‫العــام اعتراضــه علــى احلكــم بالئحــة اعتراضيــة ‪ ،‬صــدق احلكــم مــن‬\n                                                                 ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫‪237‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ ....‬وتاريــخ ‪ ....‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ ...‬وتاريــخ ‪ ...‬ه ـ ففــي يــوم األربعــاء املوافــق‪ .....‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 01 : 00‬وفيهــا حضــر املدعــي العــام ‪....‬‬\n‫وادعــى علــى احلاضريــن معــه بتاريخ‪....‬ه ـ وأثنــاء قيــام إحــدى دوريــات‬\n‫الهيئــة مبهــام عملهــا يف منطقــة ‪ .......‬جــوار مصــرف ‪ .......‬شــاهد أعضــاء‬\n‫الهيئــة ســيارة مــن نــوع ‪ ......‬تقــف يف مــكان منــز ٍو ويف وضعيــة التشــغيل‬\n‫‪ ،‬وكان صاحبهــا قــد وضــع شماســة الســيارة علــى الزجــاج األمامــي ‪،‬‬\n‫بينمــا بقيــة زجــاج الســيارة مظلــل بالكامــل ‪ ،‬وبالتثبــت مــن وضعيتهــا‬\n‫ووضعيــة مــن فيهــا ؛ اتضــح أن الســيارة بقيــادة املدعــى عليــه ‪، .... /‬‬\n‫وبصحبتــه يف املقعــد األمامــي املدعــى عليهــا‪ .... /‬مــن غيــر محرميــة‬\n‫شــرعية بينهمــا ‪ ،‬وأنهمــا يف حالــة اختــاء محــرم شــرع ًا ‪ ،‬فتــم ضبطهمــا‬\n‫‪ ،‬وأثنــاء اصطحــاب املدعــى عليــه‪ ... /‬لدوريــة الهيئــة للتحفــظ عليــه‬\n‫فيهــا ‪ ،‬حضــرت املدعــى عليهــا‪ ، ..... /‬واملدعــى عليــه ‪ ....‬واعتديــا علــى‬\n‫رجــل الهيئــة‪ ، .... /‬وحــاوال تهريــب املدعــى عليهــا‪ ،... /‬و قامــت املدعــى‬\n‫عليهــا‪ ... /‬بأخــذ حجــر مــن األرض واعتــدت بــه علــى رجــل الهيئــة ‪... /‬‬\n‫؛ وذلــك بضربــه علــى رأســه ويديــه مــع صراخهــا علــى املدعــى عليهــا‪/‬‬\n‫‪ ...‬وطلبــت منهــا أن تهــرب ‪ ،‬فقامــت املدعــى عليهــا‪ .... /‬بالهــرب مــن‬\n‫املوقــع ‪ ،‬ثــم قامــت املدعــى عليهــا‪ ... /‬بســحب الشــنطة اليدويــة اخلاصــة‬\n‫باملدعــى عليهــا الهاربــة‪ ... /‬مــن يــد عضــو الهيئــة املعتــدى عليــه‪، .... /‬‬\n\n                                                                                     ‫‪238‬‬\n\f      ‫فيمــا كان املدعــى عليــه‪ ...... /‬يحــاول إشــغال أعضــاء الفرقــة القابضــة‬\n      ‫عــن املدعــى عليــه‪ ، ... /‬واملدعــى عليهــا‪ ... /‬وذلــك بالصــراخ والتهديــد‬\n      ‫بالقتــل والتلفــظ البــذيء ؛ كقولــه لرجــل األمــن املرافــق ألعضــاء الهيئــة‬\n      ‫حينمــا طلــب منــه إثبــات هويتــه‪( :‬أنــت حرامــي زيهــم) ‪ ،‬وتلفــظ علــى‬\n      ‫األعضــاء بقولــه‪ ( :‬أنتــم هيئــة النصــب) ‪ ،‬ثــم إنــه عمــد إلــى عضــو الهيئة‪/‬‬\n      ‫‪ - ...‬واملصــاب مــن جــراء اعتــداء املدعــى عليهــا‪... /‬عليه ‪ -‬فخنقه ‪ ،‬وقام‬\n      ‫بنتــف شــيء مــن شــعرات حليتــه ‪ ،‬فجــرى االتصــال بالدوريــات األمنيــة‬\n      ‫‪ ،‬ومتــت الســيطرة علــى الوضع‪.‬وصــدر بحــق عضــو الهيئــة‪ .... /‬تقريــر‬\n      ‫طبــي مــن مستشــفى ‪ ..............‬بالعاصمــة املقدســة يتضمــن إصابتــه‬\n      ‫بجــرح رضــي بفــروة الــرأس مــن اجلهــة اليمنــى مبقــدار (‪ )5‬ســنتيمترات‬\n      ‫‪ ،‬ومت عمــل غــرز لــه ‪ ،‬ووجــود كدمــة بالركبــة اليمنــى وكدمــة باليــد‬\n      ‫اليمنــى ومــدة الشــفاء أســبوع واحــد مــا لــم حتــدث مضاعفات‪.‬كمــا‬\n      ‫صــدر بحــق املدعــى عليهــا‪ ... /‬تقريــر طبــي مــن مستشــفى ‪................‬‬\n      ‫برقــم ‪ ...‬وتاريــخ ‪ ....‬متضمــن وجــود ســحجات ســطحية علــى الصــدر مــع‬\n      ‫كدمــة ســطحية علــى الكتــف األيســر ومــدة الشــفاء خمســة ايــام مــا لــم‬\n      ‫حتــدث مضاعفــات‪( .‬جــرى فــرز أوراق بحــق املدعــى عليهــم ‪ ... /‬و‪... ..‬‬\n      ‫فيمــا يخــص منعهمــا رجــال الهيئــة مــن أداء عملهــم وفــق املــادة (‪ )7‬مــن‬\n      ‫نظــام مكافحــة الرشــوة وأحيلــت للشــرطة مبوجــب الكتــاب رقــم (‬\n                                                 ‫‪ )60761‬وتاريــخ ‪1433/12/26‬هــ)‪.‬‬\n      ‫باســتجواب املدعــى عليهــا‪ .... /‬؛ أقــرت بــأن املدعــى عليهــا ‪ ... /‬اتصلــت‬\n      ‫بهــا وأخبرتهــا بأنهــا عنــد منزلهــم وأنهــا حضــرت مــع املدعــى عليــه‪،....‬‬\n      ‫وملــا خرجــت إليهــم وجــدت الهيئــة قــد قبضــوا علــى ‪ ...‬لركوبهــا مــع‬\n      ‫املدعــى عليــه‪ ، ... /‬وأنــه كان بصحبتهــا طفــان ‪ ،‬وملــا حضــرت إليهــم‬\n\n\n‫‪239‬‬\n\f‫طلبــت منهــا املدعــى عليهــا‪ ... /‬أخــذ جوالهــا ‪ ،‬فتقدمــت ألخــذ اجلــوال ‪،‬‬\n‫فمنعهــا رجــل الهيئــة فدفعتــه ‪ ،‬فأمســك بهــا مــن مالبســها ‪ ،‬فأخــذت‬\n‫حجــر ًا ورفعتــه بقصــد إخافــة رجــل الهيئــة ‪ ،‬وضربتــه علــى رأســه ‪،‬‬\n‫فســال منــه الــدم ‪ ،‬وأنــه أثنــاء ذلــك حضــر شــقيقها املدعــى عليــه‪،.... /‬‬\n‫وأمســك برجــل الهيئــة مــن جيبــه ‪ ،‬وأنــه أثنــاء ذلك هربــت املدعى عليها‪/‬‬\n‫‪ ....‬كمــا أقــرت بأنهــا قامــت بســحب جــوال املدعــى عليهــا‪ ... /‬مــن يــد‬\n‫رجــل الهيئــة ‪ ،‬وأنــه بعــد انتهــاء املضاربــة اتصلــت بهــا املدعــى عليهــا‪/‬‬\n‫‪ ...‬وطلبــت منهــا االتصــال باملدعــى عليــه‪ .... /‬واالتفــاق معــه علــى أنــه‬\n‫ســيوصلها مشــوار ‪ ،‬وأنهــا بالفعــل اتصلــت باملدعــى عليــه‪ .... /‬واتفقــت‬\n‫معــه علــى ذلــك كمــا أفــادت بــأن املدعــى عليــه‪ ... /‬لــم يكــن علــى علــم‬\n‫باتفاقهــا مــع املدعــى عليهــا‪ ... /‬وحضورهــا مــع املدعــى عليــه ‪.... /‬وأن‬\n‫ـاء علــى أن أشــخاص ًا يعتــدون عليهــا ‪ ،‬ولــم يكــن علــى علــم‬ ‫حضــوره بنـ ً‬\n‫بقيامهــا بدفــع رجــل الهيئة‪.‬وباســتجواب املدعــى عليــه‪ .... /‬؛ أقــر بإقامتــه‬\n‫عالقــة غيــر شــرعية مــع املدعــى عليهــا‪ .... /‬وأنــه اصطحبهــا بســيارته‬\n‫واجتهــا نحــو منــزل املدعــى عليهــا‪ ، .../‬وأنــه توقــف عنــد منــزل أهــل‬\n‫‪ ، ...‬وكانــت ســيارته مظللــة وأنــه مت إلقــاء القبــض عليــه وبصحبتــه‬\n‫املدعــى عليهــا‪ ،.... /‬وأنــه بعــد القبــض عليــه حضــرت املدعــى عليهــا‪/‬‬\n‫‪ ...‬للمدعــى عليهــا‪ ،... /‬وطلــب رجــل الهيئــة مــن ‪...‬أن تنــزل مــن ســيارته‬\n‫وتركــب بســيارة الهيئــة ‪ ،‬وأثنــاء ذلــك ســحبت ‪ ...‬يــد ‪ ...‬وطلبــت منهــا‬\n‫مفارقــة املــكان ‪ ،‬فلــم تســتجب فدفعهتــا مــن ظهرهــا ‪ ،‬وطلبــت منهــا‬\n‫أن تذهــب ملنزلهــم ‪ ،‬وأنــه حصلــت مشــادة بــن ‪ ..‬ورجــل الهيئــة ‪ ،‬وشــاهد‬\n‫رجــل الهيئــة ينــزف دم ـ ًا كمــا أقــر بأنــه اســتقبل مكاملــة مــن املدعــى‬\n‫عليهــا‪ ،... /‬وطلبــت منــه أن يوهــم الســلطات بأنــه كان متوقف ـ ًا عنــد‬\n\n\n                                                                                    ‫‪240‬‬\n\f      ‫املدعــى عليهــا‪ ... /‬ليوصلهــا مشــوار وأن يخفــي أمــر وحقيقــة اصطحابــه‬\n      ‫للمدعــى عليهــا‪.... /‬وبســماع أقــوال املدعــى عليــه‪ ..... /‬أقــر بحضــوره‬\n      ‫ملســرح اجلرميــة ‪ ،‬وقيامــه باإلمســاك برجــل الهيئــة مــن جيبه‪.‬وباســتجواب‬\n      ‫املدعــى عليهــا ‪.... /‬وجــرى أقــرت بعالقتهــا باملدعــى عليــه‪ ، ..../‬وأنهــا‬\n      ‫متفقــة معــه علــى الــزواج ‪ ،‬وأنهــا ركبــت معــه بســيارته بعــد اتفاقهــا مــع‬\n      ‫املدعــى عليهــا‪ ... /‬علــى أن يأتــوا ألخذهــا مــن منزلهــم للذهــاب إلحــدى‬\n      ‫املطربــات لتســليمها عربــون إقامــة حفلــة الطــرب يف زواج أحــد إخــوة ‪،..‬‬\n      ‫وكانــت‪ ...‬علــى علــم مبقدمهــا مــع املدعــى عليــه‪ ، .... /‬وأنهــا اتصلــت‬\n      ‫بهــا وأخبرتهــا بوجودهــم عنــد منزلهــم ‪ ،‬وبعــد ذلــك حضــرت الهيئــة ‪،‬‬\n      ‫وقبضــت عليهــم ‪ ،‬واصطحبــوا املدعــى عليــه‪ ... /‬للدوريــة الرســمية ‪،‬‬\n      ‫وبقيــت هــي يف نفــس الســيارة ‪ ،‬وأثنــاء وجــود رجــل الهيئــة جــوار ســيارة‬\n      ‫املدعــى عليــه‪ ..... /‬والتــي هــي بداخلهــا حضــرت املدعــى عليهــا ‪..... /‬‬\n      ‫وســألت عــن الوضــع ‪ ،‬فطلبــت املدعــى عليهــا ‪.../‬مــن رجــل الهيئــة أن‬\n      ‫تركــب معهــا املدعــى عليهــا‪.... /‬فرفــض وكانــت حتــاول إخفــاء الوضــع‬\n      ‫وطلــب منهــا رجــل الهيئــة جوالهــا بعــد أن ضبــط شــنطتها ‪ ،‬فرفضــت‬\n      ‫تســليمه اجلــوال وطلــب منهــا الرجــوع للمقعــدة اخللفيــة حيــث كانــت‬\n      ‫راكبــة يف املقعــد األمامــي ‪ ،‬وأثنــاء ذلــك قامــت املدعــى عليهــا‪ ... /‬بفتــح‬\n      ‫بــاب الســيارة اخللفــي وطلبــت منهــا النــزول مــن الســيارة ‪ ،‬وكان رجــل‬\n      ‫الهيئــة يدفــع بــاب الســيارة ‪ ،‬فقامــت ‪.‬املدعــى عليهــا‪ .. /‬بفتــح البــاب ‪،‬‬\n      ‫وســحبها مــن الســيارة وأخــذت تدفعهــا باجتــاه منزلهــم لتهــرب ‪ ،‬وأثنــاء‬\n      ‫ذلــك حضــر املدعــى عليــه‪ ( .... /‬أخــو املدعــى عليهــا‪ )... /‬فدفــع رجــل‬\n      ‫الهيئــة فســقط علــى األرض ‪ ،‬وســارت هــي باجتــاه منــزل أهــل املدعــى‬\n      ‫عليهــا‪ ، ... /‬ودخلــت هنــاك ‪ ،‬وبقيــت فيــه ‪ ،‬كمــا أقــرت بأنهــا شــاهدت‬\n\n\n‫‪241‬‬\n\f‫املدعــى عليهــا‪ ... /‬تتشــاد ُد مــع رجــل الهيئــة ‪ ،‬وأنهــا شــاهدته ينــزف دما ؛‬\n‫ا أحضــر‬   ‫وذلــك بعــد دخولهــا منــزل أهــل‪ ...‬وأنــه قرابــة الســاعة الثالثــة ليـ ً‬\n‫أخــوات املدعــى عليهــا ‪ ... /‬لهــا جوالهــا وشــنطتها وقــد انتهــى التحقيــق‬\n‫إلــى توجيــه االتهــام لــكل مــن املدعــى عليهمــا‪ .... :‬و ‪ ....‬بإقامــة عالقــة‬\n‫غيــر شــرعية بينهمــا واختالئهمــا ببعــض يف ســيارة املدعــى عليــه ‪،...‬‬\n‫وهــروب املدعــى عليهــا‪ .../‬مــن رجــال الهيئــة ‪ ،‬وتوجيــه االتهــام للمدعــى‬\n‫عليهــا ‪ .... /‬باالعتــداء علــى أحــد رجــال الهيئــة بالضــرب ممــا تســيبب‬\n‫يف إصابتــه بجــرح يف رأســه وكدمــات يف جســمه وتهريــب املدعــى‬\n‫عليهــا ‪ ....‬والتســتر عليهــا وحتريضهــا علــى تضليــل احلقائــق باالتفــاق‬\n‫معهــا علــى ســرد واقعــة أخــرى ‪ ،‬وتوجيــه االتهــام للمدعــى عليــه‪..... /‬‬\n‫بتهديدالفرقــة القابضــة مــن أعضــاء الهيئــة بالقتــل ‪ ،‬والصــراخ عليهــم‬\n‫‪،‬والتلفــظ عليهــم بألفــاظ بذيئــة واتهامهــم بأنهــم (حراميــة) ‪ ،‬وأن‬\n‫جهازهــم جهــاز نصــب ‪ ،‬واالعتــداء علــى أحــد رجــال الهيئــة وذلــك‬\n‫بخنقــه ‪ ،‬واإلمســاك بــه مــن جيبــه ‪ ،‬ونتــف شــعرات مــن حليتــه وذلــك‬\n‫لألدلــة والقرائــن التاليــة ‪ -1 :‬مــا جــاء يف إقرارتهــم ‪ -‬املنــوه عنهــا ‪-‬‬\n‫املدونــة علــى الصفحــات رقــم ( ‪ )....‬مــن ملفــات التحقيــق واالســتدالل‬\n‫املرفقــة برقــم ( ‪ )...‬وبرقــم (‪ -2.)....‬مــا جــاء يف شــهادة الشــهود املدونــة‬\n‫مبحضــر القبــض والتفتيــش ‪ -‬املنــوه عنــه ‪ -‬املرفــق برقــم (‪ -3.)...‬مــا‬\n‫جــاء يف التقاريــر الطبيــة ‪ -‬املنــوه عنهــا ‪ -‬واملرفقــة برقــم (‪.)...‬وحيــث إن‬\n‫مــا أقــدم عليــه املدعــى عليهــم املذكــورون فعــل محــرم ومعاقــب عليــه‬\n‫شــرع ًا ؛ لــذا أطلــب إثبــات مــا أســند إليهــم ‪ ،‬واحلكــم عليهــم بعقوبــة‬\n‫تعزيريــة رادعــة لهــم ‪ ،‬وزاجــرة لغيرهــم ‪ ،‬والتشــديد يف العقوبــة علــى‬\n‫كل مــن املدعــى عليهمــا‪ ، ... /‬و‪....‬لقــاء اعتدائهمــا علــى أعضــاء هيئــة‬\n\n\n                                                                                           ‫‪242‬‬\n\f      ‫األمــر باملعــروف والنهــي عــن املنكــر ؛ اســتناد ًا لتعميــم صاحــب الســمو‬\n      ‫امللكــي وزيــر الداخليــة رقــم (‪2‬س‪/25236/‬د) وتاريــخ ‪1428/4/13‬هـ‪.‬‬\n      ‫(علمــا بــأن احلــق اخلــاص مــا زال قائم ـاً) وبســؤال املدعــى عليــه ‪...‬أجــاب‬\n      ‫ا مــا ذكــره املدعــي العــام يف دعــواه أعــاه صحيح ـ ًا كلــه جملــة‬           ‫قائ ـ ً‬\n      ‫ا وهــي اآلن زوجتــي هكــذا أجــاب وبســؤال املدعــى عليهــا ‪...‬‬             ‫وتفصي ـ ً‬\n      ‫أجابــت قائلــة كا ذكــره املدعــي العــام يف دعــواه أعــاه صحيــح كلــه‬\n      ‫ا هكــذا أجابــت وبســؤال املدعــى عليهــا ‪ ...‬أجابــت قائلــة‬      ‫جملــة وتفصيـ ً‬\n      ‫ا‬ ‫مــا ذكــره املدعــي العــام يف دعــواه أعــاه صحيــح كلــه جملــة وتفصيـ ً‬\n      ‫إال أننــي لــم أعــرف أنــه رجــل الهيئــة هكــذا أجابــت وبســؤال املدعــى‬\n      ‫ا مــا ذكــره املدعــي العــام يف دعــواه أعــاه‬      ‫عليــه الرابــع ‪ ...‬أجــاب قائ ـ ً‬\n      ‫صحيــح كلــه إال أننــي أمســكت بجيبــه العلــوي ولــم أنتــف شــعرات‬\n      ‫اللحيــة هــذه إجابتــي هــذا فتــم أطالعنــا علــى محضــر الهيئــة واملرفــق‬\n      ‫باملعاملــة لفــة رقــم ‪....‬واملتضمــن قيــام املدعــى عليــه الرابــع ‪ ...‬باشــغال‬\n      ‫لبقيــة أعضــاء الفرقــة والضــراخ والتلفــظ عليهــم بقولــه أنتــم هيئــة‬\n      ‫ا غيــر صحيــح‬     ‫النصــب أ‪-‬ه ـ وبعرضــه علــى املدعــى عليــه أجــاب قائ ـ ً‬\n      ‫وقــد اعتديــت عليــه ولــم أكــن أعلــم بأنــه رجــل هيئــة هكــذا أجــاب‬\n      ‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليهــم ومبــا‬\n      ‫أن اإلقــرار حجــة شــرعية علــى املقــر لــذا وجلميــع مــا تقــدم فقــد ثبــت لــدي‬\n      ‫إدانــة املدعــى عليهــم مبــا أســند إليهــم مــن دعــوى املدعــي العــام وقــررت‬\n      ‫مــا يلــي أوال قــررت تعزيــر املدعــى عليهمــا ‪ ....‬و‪ ...‬بجلــد كل واحــد‬\n      ‫منهمــا ســتون جلــده لقــاء اختالئهمــا احملــرم شــرعا ثاني ـ ًا قــررت تعزيــر‬\n      ‫املدعــى عليهــا الثالثــة ‪ ...‬بجلدهــا ســبعون جلــده مفرقــة علــى دفعتــن‬\n      ‫كل دفعــة خمســة وثالثــون جلــده بــن كل دفعــة وأخــرى اســبوع ثالث ـ ًا‬\n\n\n‫‪243‬‬\n\f‫قــررت تعزيــر املدعــى عليــه الرابــع بســجنه مــدة أســبوعني محســوب ًا منهــا‬\n‫إيقافــه يف هــذه القضيــة وجلــده ســبعون جلــده مفرقــة علــى دفعتــن كل‬\n‫دفعــة خمســة وثالثــون جلــده بــن كل دفعــة وأســبوع ومبــا ســبق كلــه‬\n‫حكمــت وبعــرض احلكــم املدعــى عليهــم قــررا القناعــة باحلكــم كمــا‬\n    ‫قــرر املدعــي العــام االعتــراض بالئحــة وبــاهلل التوفيــق حــرر يف‪...‬ه ـ ‪.‬‬\n            ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده وبعد ‪-:‬‬\n‫فقــد جــرى منــا نحــن قضــاة االســتئناف بالدائــرة اجلزائيــة السادســة‬\n‫مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة جــرى منــا اإلطــاع على‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة‬\n‫برقــم (‪ )....‬وتاريــخ (‪ )....‬املرفــق بهــا القــرار الصــادر مــن فضيلــة الشــيخ‪/‬‬\n‫‪ ،....‬القاضــي باحملكمــة اجلزائيــة مبكــة املكرمــة برقــم (‪ )....‬وتاريــخ‬\n‫(‪ )...‬املتضمــن دعــوى املدعــي العــام ضــد‪ ... /‬مينــي اجلنســية ورفقــاه‬\n‫املتهمــن يف اختــاء ومقاومــة رجــال الهيئــة‪ ،‬احملكــوم فيــه مبــا دون‬\n‫باطنــه‪ ،‬وبدراســة القــرار وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت‬\n‫املوافقــة علــى احلكــم لقــاء احلــق العــام‪ ،‬واهلل املوفــق وصلــى اهلل علــى‬\n                                      ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                       ‫‪244‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":236,"source_page_end":244,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3fc6d0500397abfcea49a5eb505dfd0822e339fccde342f3ece6aee9e4137a4f","normalized_text_hash":"19dc9aad6f5a3b45827a0f589dcd7c6fd8091ed46e96d68141ad36e416c5bf20","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p236-3461835"},{"id":"e4fc6037-fab3-5bdc-a1f5-5d8a11858548","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء -حق عام -صدم السيارة عمد ا وإحداث تلفيات بها -التلفظ على املجني عليه -تقدير شيخ املعارض للتلفيات -اإلقرار بصدم سيارة املجني عليه والتلفظ عليه -التعزير بالسجن واجللد.","document_number":"3460551","case_number":"34114046","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باملنطقة الشرقية على املعاملة املقيدة لدى المحكمة ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/11","year":"1434","subject":"إيذاء -حق عام -صدم السيارة عمد ا وإحداث تلفيات بها -التلفظ على املجني عليه -تقدير شيخ املعارض للتلفيات -اإلقرار بصدم سيارة املجني عليه والتلفظ عليه -التعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك ‪ 3460551 :‬تاريخه‪1434/03/11 :‬هـ‬\n                          ‫رقم الدعوى‪34114046:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34181036‬تاريخه‪1434/4/7 :‬هـ‬\n\n\n\n      ‫إيــذاء ‪ -‬حــق عــام ‪ -‬صــدم الســيارة عمــد ًا وإحــداث تلفيــات بهــا ‪ -‬التلفظ‬\n      ‫علــى املجنــي عليــه‪ -‬تقديــر شــيخ املعــارض للتلفيــات ‪ -‬اإلقــرار بصــدم‬\n            ‫ســيارة املجنــي عليــه والتلفــظ عليــه‪ -‬التعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n                           ‫ض َب ْع َد ِإ ْص َل ِح َها )‪.‬‬               ‫‪ -‬قول اهلل تعالى‪َ ( :‬و َل ُت ْف ِس ُدوا ِف ْ َ‬\n                                                                  ‫ال ْر ِ‬\n                                          ‫الل ال ُي ِح ُّب ْالُ ْع َتدِ َ‬\n                                       ‫ين )‬                                    ‫‪ -‬قوله تعالى ‪َ ( :‬وال َت ْع َت ُدوا ِإ َّن َّ َ‬\n      ‫دم ـ ُه‬\n            ‫((كل املســلم علــى املســلم حــرا ٌم ُ‬                 ‫ُّ‬              ‫‪ -‬قولــه صلــى اهلل عليــه وســلم‪:‬‬\n                                                                                                             ‫وعرضــه))‬\n                                                                                                                     ‫ُ‬            ‫وما ُل ـ ُه‬\n      ‫اض ُكـ ْـم‬\n               ‫كـ ْـم َوأ َْم َوا َل ُكـ ْـم َوأَعْ َر َ‬‫‪ -‬قولــه صلــى اهلل عليــه وســلم ‪((:‬فَ ـ ِإ َّن د َِم َاء ُ‬\n      ‫كـ ْـم‬  ‫ك ْم َهـ َـذا ‪ِ ،‬ف َب َلدِ ُ‬       ‫ك ُح ْر َم ـ ِة َي ْومِ ُكـ ْـم َهـ َـذا ‪ِ ،‬ف َشــهْ ِر ُ‬     ‫َحـ َـرا ٌم َع َل ْي ُكـ ْـم َ‬\n                                                                                                                                 ‫َهـ َـذا ))‬\n\n\n\n\n      ‫أســفر التحقيــق عــن توجيــه االتهــام للمدعــى عليــه بصــدم ســيارة املدعــي‬\n      ‫باحلــق اخلــاص عمـ ًـدا وإحــداث تلفيــات بهــا والتلفــظ عليــه نتيجــة ســوء‬\n      ‫تفاهــم بينهمــا‪ ،‬وذلــك بعــد القبــض عليــه إثــر ورود بــاغ مــن املدعــي‬\n      ‫باحلــق اخلــاص مفــاده تعرضــه للتلفــظ وصــدم ســيارته عمـ ًـدا مــن قبــل‬\n      ‫قائــد مركبــة أخــرى ســبب ســوء تفاهــم حــدث بينهمــا بالطريــق العــام‪،‬‬\n\n‫‪245‬‬\n\f‫وهــروب املدعــى عليــه مــن املوقــع بعــد ذلــك إلــى جه ـ ٍة غيــر معلومــة ‪-‬‬\n‫صــدرت ثــاث تســعيرات مــن قبــل شــيخ املعــارض للتلفيــات احلاصلــة يف‬\n‫ســيارة املب ِّلــغ ‪ :‬األولــى مببلــغ خمســة آالف وخمســمائة ‪ ،‬والثانيــة مببلــغ‬\n‫ســتة آالف ‪ ،‬والثالثة مببلغ ســتة آالف وخمســمائة‪ ،‬بالبحث عن ســوابق‬\n‫املدعــى عليــه لــم يعثــر لــه علــى ســوابق‪ ،‬طلــب املدعــي العــام إثبــات مــا‬\n‫أســند إليــه‪ ،‬واحلكــم عليــه بعقوبــة تعزيريــة‪ ،‬بعــرض دعــوى املدعــي‬\n‫العــام علــى املدعــى عليــه صــادق عليهــا جملة وتفصيالً‪ ،‬وقــرر ندمه على‬\n‫مــا بــدر منــه‪ -‬جــرى االطــاع علــى كــرت ســوابق املدعــى عليــه املشــار‬\n‫ألن املدعــى عليــه أقـ َّـر بدعــوى املدعــي العــام باتهامــه بصــدم‬\n                                                                    ‫إليــه‪ ،‬نظــر ًا َّ‬\n‫ســيارة املدعــي باحلــق اخلــاص عمــد ًا وإحــداث تلفيــات بهــا والتلفــظ عليــه‬\n‫أن مــا صــدر منــه مــن احملـ َّـرم شــرع ًا‬\n                                            ‫بســبب ســوء تفاهــم بينهمــا ومبــا َّ‬\n‫ممــا يســتوجب تعزيــر املدعــى عليــه لــذا وألجــل احلــق العــام ثبتــت إدانــة‬\n‫املدعــى عليــه مبــا نســب إليــه ومت احلكــم بتعزيــره بســجنه ثالثــة أشــهر‬\n‫وبجلــده ســبعني جلــدة مفرقــة علــى دفعتــن ‪،‬و بعــرض احلكــم علــى‬\n‫املدعــى عليــه قــرر قناعتــه بــه وطلــب املدعــي العــام رفــع كامــل أوراق‬\n‫املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم دون الئحــة اعتراضيــة‪،‬‬\n            ‫وبعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n                                                                                          ‫‪246‬‬\n\f      ‫ـدي‬\n       ‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ ال نبــي بعــده وبعــد فلـ َّ‬\n      ‫ـاء علــى املعاملــة‬\n                        ‫أنــا ‪ ........‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنـ ً‬\n      ‫الــواردة إلينــا مــن دائــرة التحقيــق واالدعــاء العــام مبحافظــة األحســاء‬\n      ‫برقــم ‪ 3594‬وتاريخ‪1434/03/08‬ه ـ واملقيــدة بهــذه احملكمــة‬\n      ‫برقم‪34600253‬وتاريخ‪1434/03/09‬ه ـ واحملالــة إلينــا مــن فضيلــة‬\n      ‫الرئيــس برقم‪34114046‬وتاريخ‪1434/03/09‬ه ـ فتحــت اجللســة وفيهــا‬\n      ‫حضــر املدعــي العــام ‪........‬امل َُع ّمــد بالترافــع أمــام احملكمــة طرفنــا‬\n      ‫مبوجــب خطــاب ســعادة رئيــس دائــرة التحقيــق واالدعــاء العــام مبحافظــة‬\n      ‫ا‬\n      ‫األحســاء ذي الرقــم ‪........‬والتاريــخ ‪1433/12/1‬ه ـ وقـ ّـرر دعــواه قائ ـ ً‬\n      ‫عامــا بدائــرة االدعــاء العــام مبحافظــة األحســاء‬   ‫‪ :‬فبصفتــي مدعي ـ ًا ً‬\n      ‫أدعــي علــى ‪ 32 ، ........:‬عام ـ ًا ‪ ،‬محصــن ‪ ،‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم (‪ ، )........‬عســكري ‪ ، .............‬أوقــف بتاريــخ ‪/ 3‬‬\n      ‫‪ 1433 / 12‬ه ـ ‪ ،‬وأحيــل إلــى شــعبة ســجن محافظــة األحســاء اســتنا ًدا‬\n      ‫للمــادة ( ‪ ) 112‬مــن نظــام اإلجــراءات اجلزائيــة الفقــرة ( ‪ ) 10‬مــن‬\n      ‫ا‬\n      ‫القــرار الــوزاري ( ‪ ) 1900‬املــؤرخ يف ‪ 1428 / 7 / 9‬ه ـ ‪ ،‬وســجل نزيـ ً‬\n      ‫لديهــم برقــم ( ‪.(........‬إنــه بتاريــخ ‪ 1433 / 11 / 27‬ه ـ ورد يف تقريــر‬\n      ‫الدوريــات األمنيــة مبحافظــة األحســاء عــن ورود بــاغ مــن املواطــن ‪/‬‬\n      ‫‪ (........‬ســعودي اجلنســية ) عــن تعرضــه للتلفــظ وصــدم ســيارته مــن‬\n      ‫نــوع ( ‪ ) .......‬اللــون أبيــض حتمــل اللوحــة ‪........‬عمـ ًـدا مــن قبــل قائــد‬\n      ‫مركبــة مــن نــوع ( ‪ ) ........‬حتمــل اللوحــة (‪ )........‬بســبب ســوء تفاهــم‬\n      ‫حــدث بينهمــا بالطريــق العــام ‪ ،‬وهــروب املدعــى عليــه مــن املوقــع بعــد‬\n\n‫‪247‬‬\n\f‫ذلــك إلــى جهـ ٍة غيــر معلومــة ‪ ،‬ومت طلبــه مــن مرجعــه وإيقافــه ومبعاينــة‬\n‫ســيارة املب ِّلــغ والتــي هــي مــن نــوع ( ‪ )......‬اللــون أبيــض حتمــل اللوحــة‬\n‫‪........‬اتضــح وجــود صدمــة بالرفــرف األمامــي األيســر ‪ ،‬وقــد صــدرت‬\n‫ثــاث تســعيرات مــن قبــل شــيخ املعــارض للتلفيــات احلاصلــة يف ســيارة‬\n‫املب ِّلــغ ‪ :‬األولــى مببلــغ خمســة آالف وخمســمائة ‪ ،‬والثانيــة مببلــغ ســتة‬\n‫آالف ‪ ،‬والثالثــة مببلــغ ســتة آالف وخمســمائة وبضبــط أقــوال املب ِّلــغ ‪/‬‬\n‫‪........‬أفــاد بأنــه قبــل صــاة العشــاء مــن يــوم الســبت وأثنــاء توجهــه ملنزلــه‬\n‫بحــي ‪........‬علــى ســيارته املشــار إليهــا يف البــاغ وكان يرافقــه عامــل‬\n‫مــن اجلنســية الهنديــة إلصــاح ( تلفزيــون ) لديــه ‪ ،‬وأثنــاء ذلــك وبالقــرب‬\n‫مــن احــد التقاطعــات إذا بســيارة مــن نــوع ( ‪ ) .....‬صنــع عــام ( ‪ 2007‬م )‬\n‫اللــون رصاصــي يقــوم بكبــس النــور خلفــه ‪ ،‬فأفســح لــه الطريــق إال أن‬\n‫أي اهتمــام ‪ ،‬فقــام صاحــب‬    ‫صاحــب تلــك الســيارة قــام بحـ ِّـده فلــم ُي ِعـ ْـر ُه َّ‬\n‫تلــك الســيارة بالتوقــف عنــد التقاطــع وحصــل بينهمــا مشــادة كالميــة‬\n‫ـاحا مــن نــوع مســدس ربــع (‬   ‫وبصــق املدعــى عليــه يف وجهــه ورفــع سـ ً‬\n‫حتقيقــا إشــهار الســاح ) اللــون أســود وهــدد بــه ‪ ،‬وعندمــا‬             ‫ً‬       ‫لــم يثبــت‬\n‫حــاول هــو النــزول لــه قــام املدعــى عليــه بصدمــه بالرفــرف األيســر‬\n‫األمامــي والذ بالفــرار وبضبــط أقــوال الشــاهد ‪ (........ /‬هنــدي اجلنســية‬\n‫) أفــاد بأنــه كان برفــق املب ِّلــغ علــى ســيارته املشــار إليهــا يف البــاغ ‪،‬‬\n‫وكانــا متجهــان إلــى منــزل املب ِّلــغ إلصــاح ( التلفزيــون ) ‪ ،‬ويف الطريــق‬\n‫بحــي ‪........‬قــام صاحــب ســيارة مــن نــوع ( ‪ ) ....‬اللــون رصاصــي ال توجــد‬\n‫بهــا لوحــات مبضايقتهمــا ‪ ،‬ثــم توقــف عنــد التقاطــع فتوقــف املب ِّلــغ ‪،‬‬\n‫وحصلــت بينهمــا مشــادة كالميــة ‪ ،‬وســمع املدعــى عليــه يتلفــظ علــى‬\n‫املب ِّلــغ ويهاجمــه ‪ ،‬وبعدهــا قــام بصــدم ســيارته والذ بالفــرار ‪ ،‬كمــا‬\n\n\n                                                                                                   ‫‪248‬‬\n\f      ‫أي ســاح وباســتجواب املدعــى عليــه أقــر أنــه يف‬    ‫أضــاف بأنــه لــم يشــاهد َّ‬\n      ‫مســاء يــوم الســبت بعــد صــاة العشــاء حــدث بينــه وبــن صاحــب ســيارة‬\n      ‫مــن نــوع (‪ )........‬بيضــاء اللــون ســوء تفاهــم ‪ ،‬وذلــك بالقــرب مــن قاعــة‬\n      ‫‪........‬للمؤمتــرات ممــا دعــاه إلــى القيــام بالتلفــظ عليــه وصــدم ســيارته‬\n      ‫عمـ ًـدا ممــا أحلــق بهــا تلفيــات ‪،‬والهــرب بعــد ذلــك علــى ســيارته مــن نــوع‬\n      ‫( ‪ ) .......‬اللــون فضــي حتمــل اللوحــة ‪........‬وقــد أســفر التحقيق عن توجيه‬\n      ‫االتهــام لــه بصــدم ســيارة املبلــغ عمـ ًـدا وإحــداث تلفيــات بهــا والتلفــظ‬\n      ‫عليــه نتيجــة ســوء تفاهــم بينهمــا ؛ وذلــك لألدلــة والقرائــن التاليــة ‪- 1:‬مــا‬\n      ‫جــاء يف أقــوال املدعــى عليــه املنــوه عنهــا ‪ ،‬واملــدون علــى الصفحــة رقــم‬\n      ‫( ‪ ) 16 ، 14‬مــن دفتــر التحقيــق املرفــق لفــة رقــم ( ‪ - 2 ) 2‬مــا جــاء يف‬\n      ‫شــهادة الشــاهد املنــوه عنهــا ‪ ،‬واملدونــة علــى الصفحــة رقــم ( ‪ ) 13‬مــن‬\n      ‫دفتــر التحقيــق املرفــق لفــة رقــم ( ‪ - 3 ) 2‬مــا ورد يف محضــر املعاينــة‬\n      ‫املنــوه عنــه ‪ ،‬واملــدون علــى الصفحــة رقــم ( ‪ ) 3 , 2‬مــن دفتــر التحقيــق‬\n      ‫املرفــق لفــة رقــم ( ‪ - 4 ) 2‬مــا ورد يف تســعيرات شــيخ املعــارض املنــوه‬\n      ‫عنهــا ‪ ،‬واملرفقــة لفــة رقــم ( ‪) 31 ، 29‬وبالبحــث عمــا إذا كان عليــه‬\n      ‫ســوابق لــم يعثــر لــه علــى ســوابق مســجلة عليــه حتــى تاريخــه وحيــث إن‬\n      ‫مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة شــرع ًا فعــل‬\n      ‫محــرم ومعاقــب عليــه شــرع ًا ؛ أطلــب إثبــات مــا أســند إليــه ‪ ،‬واحلكــم‬\n      ‫عليــه بعقوبــة تعزيريــة تزجــره وتــردع غيــره ‪ ،‬والتشــديد عليــه يف العقوبــة‬\n      ‫كونــه عســكري مــن املؤمــل منــه احملافظــة علــى النظــام وعــدم مخالفة‬\n      ‫قائمــا ) ‪ .‬هكــذا ا َّدعــى ؛ عليــه‬\n                                        ‫أن احلــق اخلــاص ال زال ً‬   ‫علمــا َّ‬\n                                                                           ‫األنظمــة ( ً‬\n      ‫فقــد حضــر املدعــى عليــه وبعــد التأكــد مــن هويتــه جــرى عــرض دعــوى‬\n      ‫ا ‪ :‬مــا ذكــره املدعــي العــام مــن اتهامــي‬‫املدعــي العــام عليــه فأجــاب قائـ ً‬\n\n\n‫‪249‬‬\n\f‫بصــدم ســيارة املواطــن ‪........‬عمــد ًا وإحــداث تلفيــات بهــا والتلفــظ عليــه‬\n‫كل ذلــك صحيــح وذلــك بســبب ســوء تفاهــم بيننــا يف الطريــق وأنــا‬\n‫نــادم علــى مــا بــدر منــي هكــذا أجــاب ثــم جــرى االطــاع علــى جميــع‬\n‫أوراق املعاملــة ومنهــا ‪ :‬كــرت ســوابق املدعــى عليــه املتضمــن عــدم‬\n‫وجــود ســوابق عليــه كمــا جــرى االطــاع علــى مذكــرة إيقــاف املدعــى‬\n‫ـاء علــى مــا تقــدم‬           ‫عليــه املتضمنــة أنــه أوقــف بتاريخ‪1433/12/03‬ه ـ فبنـ ً‬\n‫مــن الدعــوى واإلجابــة وبعــد النظــر يف حــال املدعــى عليــه والتأكــد‬\n‫أن املدعــى عليــه‬            ‫مــن أهليتــه وبعــد دراســة أوراق املعاملــة وتأملهــا ومبــا َّ‬\n‫أقـ َّـر بدعــوى املدعــي العــام باتهامــه بصــدم ســيارة املواطــن ‪........‬عمــد ًا‬\n‫أن‬ ‫وإحــداث تلفيــات بهــا والتلفــظ عليــه بســبب ســوء تفاهــم بينهمــا ومبــا َّ‬\n‫ض َب ْع َد‬   ‫ال ْر ِ‬‫(و َل ُت ْف ِسـ ُـدوا ِف ْ َ‬      ‫احملرم شــرع ًا قــال تعالى‪َ :‬‬            ‫َّ‬         ‫مــا صــدر منــه مــن‬\n‫الل ال ُي ِحـ ُّـب ْال ُْع َتدِ يـ َـن ) وقــال‬        ‫(وال َت ْع َتـ ُـدوا ِإ َّن َّ َ‬\n                                                                                      ‫ِإ ْص َلحِ َهــا ) وقــال تعالــى ‪َ :‬‬\n‫دم ـ ُه وما ُل ـ ُه‬  ‫ـرام ُ‬\n                         ‫صلــى اهلل عليــه وســلم ‪(( :‬كلُّ املســلم علــى املســلم حـ ٌ‬\n‫َكـ ْـم‬  ‫كـ ْـم َو َأ ْم َوال ُ‬  ‫‪((:‬ف ـ ِإ َّن د َِم َاء ُ‬\n                                                        ‫وعرضــه)) وقــال عليــه الصــاة والســام َ‬                         ‫ُ‬\n‫ك ْم‬    ‫كـ ْـم َهـ َـذا ‪ِ ،‬ف َشـ ْـه ِر ُ‬           ‫ك ُح ْر َم ـ ِة َي ْومِ ُ‬   ‫كـ ْـم َ‬‫كـ ْـم َحـ َـر ٌام َع َل ْي ُ‬    ‫َو َأ ْع َر َ‬\n                                                                                                                      ‫اض ُ‬\n‫كـ ْـم َهـ َـذا )) ممــا يســتوجب تعزيــر املدعــى عليــه لــذا كلــه‬                                         ‫َهـ َـذا ‪ِ ،‬ف َبلَدِ ُ‬\n‫وألجــل احلــق العــام حكمــت علــى املدعــى عليــه مبــا يلــي ‪ :‬أوالً‪ /‬ثبــت‬\n‫ـدي إدانــة املدعــى عليــه بصــدم ســيارة املواطــن ‪........‬وإحــداث تلفيــات‬                                                ‫لـ َّ‬\n‫بهــا والتلفــظ عليــه نتيجــة ســوء تفاهــم بينهمــا ثاني ـ ًا ‪ /‬يعــزر ألجــل ذلــك‬\n‫بســجنه ثالثــة أشــهر مــن تاريــخ إيقافــه علــى ذمــة القضيــة وبجلده ســبعني‬\n‫جلــدة مفرقــة علــى دفعتــن متســاويتني كل دفعــة خمــس وثالثــون جلــدة‬\n‫وبــن كل دفعــة وأخــرى مــدة ال تقــل عــن عشــرة أيــام ‪ .‬ثالث ـ ًا ‪ /‬وبتــاوة‬\n‫احلكــم علــى الطرفــن وإفهــام املدعــى عليــه بحقــه يف متييــز احلكــم قــرر‬\n\n\n                                                                                                                                         ‫‪250‬‬\n\f      ‫قناعتــه بــه وطلــب املدعــي العــام رفــع كامــل أوراق املعاملــة حملكمــة‬\n      ‫االســتئناف لتدقيــق احلكــم دون الئحــة اعتراضيــة مكتفيـ ًا مبــا ورد يف‬\n      ‫الئحــة الدعــوى وأقفلــت اجللســة الســاعة الثانيــة عشــرة والنصــف وصلــى‬\n      ‫اهلل وسـ َّـلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪ .‬حــرر يف‬\n      ‫‪1434/03/10‬ه ـ احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة‬\n      ‫الدائ ــرة اجلـزائي ــة الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية‬\n      ‫علــى املعاملــة املقيــدة لــدى احملكمــة برقــم ‪/34/752806‬ج‪ 2‬وتاريــخ‬\n      ‫‪1434/3/25‬ه ـ الــواردة مــن فضيلــة رئيس احملكمــة اجلزائية مبحافظة‬\n      ‫األحســاء برقــم ‪ 34/600253‬وتاريــخ ‪1434/3/22‬ه ـ املرفــق بهــا القــرار‬\n      ‫الصــادر مــن فضيلــة القاضــي باحملكمــة الشيخ‪......../‬املســجل برقــم‬\n      ‫‪ 3460551‬وتاريــخ ‪1434/3/11‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام‬\n      ‫ضــد‪......../‬يف قضيــة صــدم ســيارة متعمــد وقــد تضمــن القــرار حكــم‬\n      ‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه‬\n      ‫وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل‬\n                ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/4/7‬ه ـ‬\n\n\n\n\n‫‪251‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":245,"source_page_end":251,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e3a2faa2afc048948000b17dc91479217f13adacfdd80e1e4c73cf0f8f8049c6","normalized_text_hash":"f568ae72c16cd802d8a37324fde72c745297a4bdd564be45380d371cf95b2cc2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p245-3460551"}]$archive_payload$::jsonb) AS x LIMIT 25
